window.CDL_QUESTIONS = [
  { id: "gk-01", category: "general", topic: "Clase de licencia", q: "¿Qué combinación generalmente requiere un CDL Clase A de California?", choices: ["Cualquier vehículo que remolque un tráiler", "Una combinación con un GCWR de 26,001 libras o más cuando el (los) vehículo(s) remolcado(s) tienen un GVWR de más de 10,000 libras", "Cualquier camión de más de 10,000 libras de GVWR", "Cualquier vehículo de pasajeros con más de 8 asientos"], a: 1, why: "La Clase A cubre combinaciones pesadas: GCWR de 26,001 o más cuando la(s) unidad(es) remolcada(s) superan las 10,000 libras de GVWR." },
  { id: "gk-02", category: "general", topic: "Edad", q: "¿Cuál es la edad mínima para operar un CMV en comercio interestatal?", choices: ["18", "19", "20", "21"], a: 3, why: "La conducción comercial interestatal requiere 21 años. La conducción intrastatal remunerada en California puede comenzar a los 18 si se cumplen los demás requisitos." },
  { id: "gk-03", category: "general", topic: "Edad", q: "¿A qué edad puede conducir un vehículo comercial remunerado solo dentro de California, si cumple los demás requisitos?", choices: ["16", "18", "20", "21"], a: 1, why: "California permite operar un CMV remunerado en tráfico intrastatal a los 18 años. La operación interestatal requiere 21." },
  { id: "gk-04", category: "general", topic: "Inspección", q: "¿Cuándo debe completarse una inspección previa al viaje?", choices: ["Por lo menos una vez a la semana", "Solo si hubo problemas en el último viaje", "Antes de operar el vehículo", "Solo después de un accidente"], a: 2, why: "El manual exige una inspección del vehículo antes de operarlo para encontrar defectos antes de conducir." },
  { id: "gk-05", category: "general", topic: "Inspección en ruta", q: "Cada vez que se detenga durante un viaje, debe revisar:", choices: ["Solo el medidor de combustible", "Llantas, ruedas, frenos, luces y sujeción de la carga", "Solo los documentos de la carga", "Solo los espejos"], a: 1, why: "Las revisiones en ruta incluyen llantas, ruedas/rines, frenos, iluminación, dispositivos de acoplamiento y amarras de la carga." },
  { id: "gk-06", category: "general", topic: "Visión", q: "¿A qué distancia hacia adelante debe mirar generalmente un conductor comercial?", choices: ["2–3 segundos", "5–6 segundos", "12–15 segundos", "Solo aproximadamente una cuadra de la ciudad de noche"], a: 2, why: "Mirar de 12 a 15 segundos hacia adelante da tiempo para detectar peligros y planear una respuesta suave." },
  { id: "gk-07", category: "general", topic: "Distancia de seguimiento", q: "Por debajo de 40 mph, una regla segura de distancia de seguimiento es:", choices: ["Un segundo por cada 10 pies de longitud del vehículo", "Dos segundos en total", "Un segundo por cada eje", "Cinco segundos en total sin importar la longitud"], a: 0, why: "Deje por lo menos 1 segundo por cada 10 pies de longitud del vehículo a velocidades menores de 40 mph." },
  { id: "gk-08", category: "general", topic: "Distancia de seguimiento", q: "Al viajar a más de 40 mph, ¿qué debe agregar a la regla básica de distancia de seguimiento?", choices: ["Nada", "Un segundo extra", "Cinco segundos extra", "Un segundo extra por eje"], a: 1, why: "Por encima de 40 mph, agregue 1 segundo extra a la regla de 1 segundo por cada 10 pies." },
  { id: "gk-09", category: "general", topic: "Curvas", q: "¿Cuál es la forma más segura de tomar una curva en un vehículo comercial?", choices: ["Frenar con fuerza en la curva", "Cambiar de marcha en medio de la curva", "Reducir a una velocidad segura antes de entrar y luego acelerar ligeramente a través de ella", "Usar la velocidad publicada para autos sin importar la carga"], a: 2, why: "Reduzca la velocidad antes de la curva. Frenar en una curva puede bloquear las ruedas y causar un derrape o volcadura." },
  { id: "gk-10", category: "general", topic: "Curvas", q: "¿Por qué es peligroso frenar en una curva?", choices: ["Hace que el motor se sobrecaliente", "Las ruedas pueden bloquearse y el vehículo puede derrapar o volcarse", "Carga los tanques de aire demasiado rápido", "Siempre mejora la tracción"], a: 1, why: "Frenar en una curva puede bloquear las ruedas, reducir el control de la dirección y causar un derrape o volcadura." },
  { id: "gk-11", category: "general", topic: "Despeje", q: "Si no está seguro de que su vehículo pase por debajo de un objeto elevado, usted debe:", choices: ["Acelerar para pasar rápido", "Seguir de cerca al camión de adelante", "Reducir la velocidad y usar otra ruta si el despeje sigue siendo incierto", "Conducir por el acotamiento"], a: 2, why: "Nunca adivine el despeje superior. Reduzca la velocidad, deténgase si es necesario y elija una ruta de altura conocida." },
  { id: "gk-12", category: "general", topic: "Despeje", q: "¿Cuál afirmación sobre el despeje superior es verdadera?", choices: ["Las alturas publicadas siempre son exactas", "La nieve compactada, el hielo o una superficie recién pavimentada pueden reducir el despeje", "Un tráiler vacío siempre tiene más despeje que uno cargado", "Puede ignorar las alturas publicadas de noche"], a: 1, why: "El despeje publicado puede ser incorrecto después de pavimentar, por nieve compactada u otros cambios. Conozca su altura real." },
  { id: "gk-13", category: "general", topic: "Marcha atrás", q: "La práctica más segura al dar marcha atrás es:", choices: ["Retroceder rápido para reducir la exposición", "Evitar dar marcha atrás siempre que sea posible, y bajarse y mirar primero", "Usar solo el espejo derecho", "Nunca hacer un reajuste hacia adelante"], a: 1, why: "Dar marcha atrás es una maniobra de alto riesgo de choque. Evítela cuando pueda; recorra el camino a pie y use un ayudante cuando sea necesario." },
  { id: "gk-14", category: "general", topic: "Marcha atrás", q: "Al dar marcha atrás con un tráiler, al principio gire el volante:", choices: ["En la misma dirección en que quiere que vaya el tráiler", "En la dirección opuesta a la trayectoria deseada del tráiler", "Solo después de que el tráiler se mueva rápido", "Recto, y luego espere a que el tráiler busque su camino"], a: 1, why: "Para empezar a girar el tráiler, dirija en sentido opuesto a la dirección deseada del tráiler y luego sígalo." },
  { id: "gk-15", category: "general", topic: "Detención", q: "¿Cómo debe hacer normalmente una parada segura?", choices: ["Pisar el pedal de golpe", "Aplicar la presión de los frenos de forma gradual y suave", "Pasar a neutro de inmediato", "Jalar el freno de estacionamiento mientras se mueve"], a: 1, why: "Un frenado suave y controlado mantiene el vehículo estable y reduce el riesgo de derrape." },
  { id: "gk-16", category: "general", topic: "Conducción nocturna", q: "Al conducir de noche usted debe:", choices: ["Conducir lo suficientemente despacio para detenerse dentro del alcance de los faros", "Bajar la ventanilla en lugar de descansar si tiene sueño", "Depender de la cafeína si está somnoliento", "Usar las luces altas en la niebla"], a: 0, why: "La distancia de visión nocturna es limitada. Debe poder detenerse dentro del alcance de los faros." },
  { id: "gk-17", category: "general", topic: "Fatiga", q: "Si se siente somnoliento al conducir, la acción segura es:", choices: ["Abrir la ventanilla y seguir", "Tomar café y conducir más rápido para terminar antes", "Detenerse en un lugar seguro y descansar", "Subir el volumen de la radio"], a: 2, why: "Dormir es el único remedio verdadero. Deténgase en un lugar seguro y descanse antes de continuar." },
  { id: "gk-18", category: "general", topic: "Ferrocarril", q: "Antes de cruzar las vías del ferrocarril usted debe:", choices: ["Cambiar de marcha sobre las vías para ahorrar tiempo", "Asegurarse de tener suficiente espacio para despejar las vías del otro lado", "Detenerse sobre las vías si el tráfico de adelante se mueve", "Seguir de cerca al vehículo de adelante"], a: 1, why: "Nunca empiece a cruzar a menos que todo el vehículo despeje las vías. No cambie de marcha mientras cruza." },
  { id: "gk-19", category: "general", topic: "Ferrocarril", q: "¿Por qué debe evitar cambiar de marcha al cruzar las vías del ferrocarril?", choices: ["Puede calar el vehículo sobre las vías", "Ahorra combustible", "Mejora la tracción", "Lo exige el ABS"], a: 0, why: "Calarse sobre las vías es extremadamente peligroso. Cruce en una marcha que lo lleve hasta el otro lado." },
  { id: "gk-20", category: "general", topic: "Incendios", q: "Si su vehículo se incendia, las primeras acciones son:", choices: ["Seguir conduciendo hasta un taller", "Orillarse de forma segura, estacionarse y sacar a todos", "Abrir el cofre de inmediato en un incendio del motor", "Echar agua sobre combustible en llamas"], a: 1, why: "Saque el vehículo de la calzada si puede, estacione, apague y saque a las personas antes de combatir el incendio." },
  { id: "gk-21", category: "general", topic: "Incendios", q: "El agua se puede usar de forma segura en ¿cuál de estos incendios?", choices: ["Incendios eléctricos", "Incendios de gasolina o aceite", "Combustibles ordinarios como madera, papel o tela", "Todos los anteriores"], a: 2, why: "El agua funciona en combustibles ordinarios Clase A. No use agua en incendios eléctricos o de combustible." },
  { id: "gk-22", category: "general", topic: "Dispositivos de advertencia", q: "Si se descompone, los dispositivos reflectantes de advertencia deben colocarse:", choices: ["Solo detrás del camión, a 10 pies", "Según la dirección del tráfico, el tipo de carretera y la distancia de visibilidad", "Dentro de la cabina", "Directamente debajo del tráiler"], a: 1, why: "La colocación depende de si es de dos carriles, dividida, colinas y curvas, para que los conductores que se acercan vean la advertencia a tiempo." },
  { id: "gk-23", category: "general", topic: "Dispositivos de advertencia", q: "Si se detiene en una carretera de un solo sentido o dividida, coloque los triángulos reflectantes:", choices: ["A 10, 100 y 200 pies hacia el tráfico que se acerca", "Solo a 10 pies detrás del vehículo", "Solo delante del vehículo", "A 500 pies en ambos lados"], a: 0, why: "En una carretera dividida o de un solo sentido, coloque los triángulos a 10, 100 y 200 pies hacia el tráfico que se acerca." },
  { id: "gk-24", category: "general", topic: "Equipo de emergencia", q: "¿Qué tres tipos de equipo de emergencia debe tener?", choices: ["Extintor, fusibles eléctricos de repuesto (a menos que tenga disyuntores) y dispositivos de advertencia", "Cables pasa-corriente, combustible extra y una radio", "Solo un extintor", "Solo llanta de refacción, gato y llave de tuercas"], a: 0, why: "Las reglas federales/estatales exigen un extintor, fusibles de repuesto si se necesitan y dispositivos de advertencia como 3 triángulos rojos." },
  { id: "gk-25", category: "general", topic: "Llantas", q: "¿Cuál es la profundidad mínima de la banda de rodadura para las llantas delanteras (de dirección)?", choices: ["2/32 de pulgada", "4/32 de pulgada", "6/32 de pulgada", "1/8 de pulgada en un solo canal"], a: 1, why: "Las llantas del eje de dirección necesitan por lo menos 4/32 de pulgada de banda en cada canal principal. Las demás llantas necesitan 2/32 de pulgada." },
  { id: "gk-26", category: "general", topic: "Llantas", q: "¿Cuál es la profundidad mínima de la banda de rodadura para las llantas que no son las delanteras de dirección?", choices: ["1/32 de pulgada", "2/32 de pulgada", "4/32 de pulgada", "8/32 de pulgada"], a: 1, why: "Las llantas que no son de dirección deben tener por lo menos 2/32 de pulgada de profundidad de banda en cada canal principal." },
  { id: "gk-27", category: "general", topic: "Dirección", q: "La holgura de la dirección es generalmente excesiva si un volante de 20 pulgadas se mueve más de:", choices: ["1/2 pulgada antes de que se muevan las llantas", "2 pulgadas (unos 10 grados) antes de que se muevan las llantas delanteras", "6 pulgadas", "Una vuelta completa"], a: 1, why: "Más de unos 10 grados de holgura (2 pulgadas en un volante de 20 pulgadas) es un defecto que debe repararse antes de conducir." },
  { id: "gk-28", category: "general", topic: "Sistema de enfriamiento", q: "Si un recipiente de refrigerante forma parte de un sistema presurizado, usted debe:", choices: ["Quitar la tapa del radiador con el motor caliente", "Nunca quitar la tapa hasta que el sistema se haya enfriado", "Usar solo agua, nunca refrigerante", "Revisar el refrigerante solo mientras conduce"], a: 1, why: "Quitar una tapa presurizada caliente puede causar quemaduras graves. Espere a que el sistema se enfríe." },
  { id: "gk-29", category: "general", topic: "Carga", q: "Antes de iniciar un viaje, la carga debe estar:", choices: ["Cargada suelta para ventilación", "Asegurada correctamente contra el desplazamiento, la caída o el daño al vehículo", "Colocada solo en la parte trasera", "Cubierta solo si se espera lluvia"], a: 1, why: "La carga debe estar equilibrada y asegurada para que no se desplace, se caiga ni haga inestable el vehículo." },
  { id: "gk-30", category: "general", topic: "Carga", q: "¿Dónde debe colocarse normalmente la carga más pesada?", choices: ["Alta y hacia la parte trasera", "Baja y lo más cerca del centro que sea práctico", "Solo en un lado", "En el techo"], a: 1, why: "La carga baja y centrada mantiene bajo el centro de gravedad y ayuda a la dirección, la tracción y la resistencia a la volcadura." },
  { id: "gk-31", category: "general", topic: "Carga", q: "¿Por qué no debe apilarse la carga demasiado alto?", choices: ["Eleva el centro de gravedad y aumenta el riesgo de volcadura", "Siempre reduce el peso legal", "Hace el camión más silencioso", "Impide el uso de los espejos"], a: 0, why: "Un centro de gravedad alto es un factor importante de volcadura, especialmente en curvas y rampas." },
  { id: "gk-32", category: "general", topic: "Carga", q: "Las cargas en contenedores:", choices: ["Están exentas de los límites de peso", "Se usan generalmente cuando la carga se transporta en parte por ferrocarril o barco", "Nunca necesitan sujeción", "Siempre deben abrirse antes de conducir"], a: 1, why: "Los contenedores son comunes en movimientos intermodales (barco/ferrocarril/camión). Aun así deben asegurarse y ser legales en peso." },
  { id: "gk-33", category: "general", topic: "Carga", q: "Después de iniciar un viaje, ¿cuándo debe volver a revisar la sujeción de la carga?", choices: ["Solo en el destino", "Dentro de las primeras 50 millas y cada vez que cambie el estado de servicio o haya conducido 3 horas o 150 millas", "Solo con lluvia", "Nunca si el tráiler está sellado"], a: 1, why: "Las reglas federales de sujeción de carga exigen una revisión temprana y revisiones periódicas, incluida la sujeción visible de cargas selladas." },
  { id: "gk-34", category: "general", topic: "Peso", q: "El término peso bruto combinado (GCW) se refiere a:", choices: ["Solo el peso del tractocamión", "El peso total de la unidad motriz, el (los) tráiler(es) y la carga", "Solo el peso de la carga", "Solo el peso por eje"], a: 1, why: "El GCW es el peso total real de la combinación. El GCWR es la capacidad nominal." },
  { id: "gk-35", category: "general", topic: "Peso", q: "Una fórmula de puentes se usa para:", choices: ["Fijar las alturas publicadas de los puentes", "Limitar los pesos por eje según la separación de los ejes para proteger puentes y calzadas", "Calcular el impuesto al combustible", "Fijar los límites de velocidad"], a: 1, why: "Los ejes más juntos tienen permitido menos peso para no sobrecargar los puentes." },
  { id: "gk-36", category: "general", topic: "Montañas", q: "Antes de bajar una pendiente larga y empinada usted debe:", choices: ["Esperar a que aumente la velocidad y luego reducir la marcha", "Seleccionar una marcha baja segura antes de empezar a bajar", "Usar solo los frenos y permanecer en marcha alta", "Pasar a neutro para ahorrar combustible"], a: 1, why: "Elija la marcha baja adecuada antes del descenso para que el freno del motor controle la velocidad y los frenos no se sobrecalienten." },
  { id: "gk-37", category: "general", topic: "Montañas", q: "Está a punto de bajar una pendiente larga y empinada en un camión más nuevo. Usted debe:", choices: ["Usar una marcha más baja que la que usaría para subir la misma pendiente", "Usar una marcha más alta que en la subida", "Descender en neutro", "Mantener el freno ligeramente pisado todo el camino en marcha alta"], a: 0, why: "Los camiones más nuevos a menudo necesitan una marcha aún más baja al bajar que la que usaron al subir porque son más aerodinámicos y ruedan con más facilidad." },
  { id: "gk-38", category: "general", topic: "Desvanecimiento de frenos", q: "¿Por qué debe depender del freno del motor en descensos largos o empinados?", choices: ["Para evitar el calor excesivo de los frenos que puede causar desvanecimiento o falla", "Para aumentar la presión de las llantas", "Para facilitar los cambios de marcha", "Para reducir la necesidad de dirigir"], a: 0, why: "Los frenos de servicio pueden sobrecalentarse, desvanecerse y fallar. Use una marcha baja para que el freno del motor haga la mayor parte del trabajo." },
  { id: "gk-39", category: "general", topic: "Desvanecimiento de frenos", q: "Si necesita cada vez más presión de freno para mantener la misma velocidad cuesta abajo, los frenos están:", choices: ["Funcionando mejor", "Desvaneciéndose por el calor", "Ajustándose automáticamente", "Cargando los tanques de aire"], a: 1, why: "El aumento de la presión de aplicación para la misma velocidad es una señal clásica de desvanecimiento de los frenos. Reduzca la velocidad y use una marcha más baja." },
  { id: "gk-40", category: "general", topic: "Rampa de escape", q: "Si fallan los frenos en un descenso y hay una rampa de escape disponible, usted debe:", choices: ["Continuar y bombear los frenos", "Usar la rampa de escape", "Apagar el motor de inmediato mientras se mueve", "Pasar a marcha alta"], a: 1, why: "Las rampas de escape están construidas para detener vehículos descontrolados. Úsela si fallan los frenos en una pendiente." },
  { id: "gk-41", category: "general", topic: "Rampa de salida", q: "Está saliendo por una rampa curva cuesta abajo en un vehículo pesado. Usted debe:", choices: ["Tomar la rampa a velocidad de carretera", "Reducir a una velocidad segura antes de la curva", "Frenar con fuerza en medio de la curva", "Reducir la marcha en la parte más cerrada de la curva"], a: 1, why: "Las rampas suelen ser más cerradas y cuesta abajo. Reduzca antes de la curva para que el vehículo no vuelque ni se salga." },
  { id: "gk-42", category: "general", topic: "Derrapes", q: "¿Cuál es generalmente la mejor primera respuesta ante un reventón de llanta?", choices: ["Frenar con fuerza de inmediato", "Sujetar el volante con firmeza, no frenar al principio, soltar el acelerador con suavidad y detenerse de forma segura", "Girar bruscamente hacia el acotamiento", "Pasar a reversa"], a: 1, why: "Un frenazo súbito puede causar un derrape. Mantenga el control, reduzca gradualmente y luego inspeccione." },
  { id: "gk-43", category: "general", topic: "Derrapes", q: "Si las ruedas se bloquean en un camino resbaladizo en un vehículo sin ABS, usted puede:", choices: ["Ganar más control de la dirección", "Perder el control de la dirección y derrapar, plegarse en navaja o girar", "Detenerse perfectamente recto siempre", "Desconectar el tráiler de forma segura"], a: 1, why: "Las ruedas bloqueadas no dirigen. Eso puede causar un derrape, navaja o giro." },
  { id: "gk-44", category: "general", topic: "Frenado de emergencia", q: "¿Qué métodos se identifican para una parada rápida y controlada sin ABS?", choices: ["Frenado controlado o frenado intermitente (stab)", "Solo freno de estacionamiento", "Frenado en neutro por inercia", "Frenado solo con el clutch"], a: 0, why: "El frenado controlado (fuerte sin bloqueo) y el frenado intermitente (aplicar a fondo, soltar al bloquearse, volver a aplicar) son los métodos del manual." },
  { id: "gk-45", category: "general", topic: "Cinturón de seguridad", q: "¿Cuándo debe usar el cinturón de seguridad en un vehículo comercial?", choices: ["Solo con lluvia", "Solo en carreteras", "Siempre que esté en la vía", "Solo al transportar carga"], a: 2, why: "Use el cinturón de seguridad siempre que el vehículo esté en la vía. Lo mantiene en control en un choque o una parada súbita." },
  { id: "gk-46", category: "general", topic: "Estacionamiento", q: "Al dejar su vehículo comercial usted debe:", choices: ["Dejarlo solo en marcha", "Aplicar el freno de estacionamiento", "Dejar el motor encendido sin vigilancia", "Encender las luces altas"], a: 1, why: "Siempre ponga el freno de estacionamiento. También asegure el vehículo según se requiera (llaves, calzos si es necesario)." },
  { id: "gk-47", category: "general", topic: "Estacionamiento", q: "Debe planear el estacionamiento de modo que:", choices: ["Necesite salir en reversa a través del tráfico", "Pueda salir hacia adelante del espacio cuando sea posible", "El tráiler bloquee una boca de incendio", "El vehículo oculte los triángulos de advertencia"], a: 1, why: "Planee salir sin dar marcha atrás cuando pueda. Salir en reversa de un espacio es una causa común de choques." },
  { id: "gk-48", category: "general", topic: "Sentidos", q: "¿Qué cuatro sentidos le ayudan a detectar problemas del vehículo durante un viaje?", choices: ["Mirar, escuchar, oler y sentir", "Gustar, tocar, oír y adivinar", "Leer, escribir, contar y señalar", "Observar, caminar, saludar y esperar"], a: 0, why: "Use la vista, el oído, el olfato y el tacto (vibración, jalón, suavidad) para detectar problemas a tiempo." },
  { id: "gk-49", category: "general", topic: "Peligros", q: "La razón más importante para hacer una inspección del vehículo es:", choices: ["Ahorrar combustible", "Encontrar problemas que podrían causar un choque o una descompostura", "Evitar usar el cinturón de seguridad", "Omitir la prueba de destrezas"], a: 1, why: "La seguridad es el propósito: detectar defectos antes de que causen un choque, un incendio o una descompostura." },
  { id: "gk-50", category: "general", topic: "Escape", q: "Un sistema de escape con fugas es peligroso porque:", choices: ["Siempre mejora el rendimiento de combustible", "Gases venenosos como el monóxido de carbono pueden entrar a la cabina", "Carga los tanques de aire", "Enfría los frenos"], a: 1, why: "Las fugas de escape pueden introducir monóxido de carbono en la cabina, especialmente con las ventanillas cerradas." },
  { id: "gk-51", category: "general", topic: "Giros", q: "En un giro a la izquierda con un vehículo largo, usted debe:", choices: ["Empezar a girar tan pronto como la defensa entre a la intersección", "Llegar al centro de la intersección antes de empezar el giro para que la desviación de trayectoria no golpee vehículos a la izquierda", "Girar desde el acotamiento derecho", "Abrirse a la derecha hacia el carril adyacente del tráfico contrario como hábito"], a: 1, why: "Si gira demasiado pronto, el lado izquierdo se desvía hacia otros vehículos. Entre lo suficiente a la intersección primero." },
  { id: "gk-52", category: "general", topic: "Espacio", q: "Necesita espacio extra adelante cuando:", choices: ["El camino está seco y vacío", "Lo siguen de cerca, conduce con lluvia o hielo, o sigue a otro camión", "Va vacío", "Tiene ABS"], a: 1, why: "La mala tracción, la visibilidad limitada y quienes lo siguen de cerca requieren más espacio para que pueda detenerse con suavidad." },
  { id: "gk-53", category: "general", topic: "Quienes siguen de cerca", q: "Si lo siguen de cerca, usted debe:", choices: ["Frenar de golpe para “avisar” al otro conductor", "Acelerar muy por encima del límite", "Evitar cambios bruscos y abrir más espacio adelante para poder reducir gradualmente", "Moverse a la izquierda y detenerse"], a: 2, why: "No provoque a quien lo sigue de cerca. Aumente la distancia de seguimiento para que sus propias paradas sean graduales." },
  { id: "gk-54", category: "general", topic: "Hidroplaneo", q: "El hidroplaneo es más probable cuando:", choices: ["Las llantas tienen poca banda de rodadura y hay agua estancada en el camino", "Las llantas son nuevas y el camino está seco", "Conduce muy despacio en un eje de llantas duales", "El pavimento está acanalado y seco"], a: 0, why: "Los vehículos livianos, la banda desgastada y el agua estancada aumentan el riesgo de hidroplaneo. El hidroplaneo parcial puede empezar a velocidades relativamente bajas." },
  { id: "gk-55", category: "general", topic: "Invierno", q: "En invierno, debe prestar atención extra a:", choices: ["Refrigerante/anticongelante, desempañadores, limpiaparabrisas, fugas de escape y cadenas para llantas si se requieren", "Solo la radio", "Solo los documentos de la carga", "Solo el claxon"], a: 0, why: "Las revisiones de invierno se centran en ver, la protección contra congelamiento del sistema de enfriamiento, las fugas de escape hacia una cabina cerrada y el equipo de tracción." },
  { id: "gk-56", category: "general", topic: "Niebla", q: "Cuando hay niebla densa usted debe:", choices: ["Usar luces altas y mantener la velocidad de carretera", "Reducir a una velocidad acorde a la visibilidad, o detenerse fuera de la calzada en un lugar seguro si no puede ver lo suficiente para conducir", "Seguir las luces traseras de adelante lo más de cerca posible", "Conducir por el acotamiento a velocidad normal"], a: 1, why: "Si no puede ver lo suficientemente lejos para conducir con seguridad, salga de la vía en un lugar seguro y legal y espere." },
  { id: "gk-57", category: "general", topic: "Alcohol", q: "Lo pondrán fuera de servicio por 24 horas si opera un CMV con:", choices: ["Cualquier cantidad detectable de alcohol por debajo de 0.04", "Una bebida de café", "Un medicamento para el resfriado que no cause somnolencia", "Cero alcohol y un CDL válido"], a: 0, why: "Cualquier alcohol detectable por debajo de 0.04 igual significa una orden de fuera de servicio de 24 horas. 0.04 o más es una infracción de alcohol del CDL." },
  { id: "gk-58", category: "general", topic: "Horas", q: "Después de presentarse al servicio tras 10 horas de descanso, los conductores interestatales de carga en general no pueden conducir más allá de:", choices: ["La 8.ª hora", "La 11.ª hora de conducción / la ventana de la 14.ª hora en servicio", "La 24.ª hora", "La 30.ª hora"], a: 1, why: "Reglas federales interestatales: 11 horas de conducción dentro de una ventana de 14 horas después de 10 horas consecutivas de descanso (sujeto a los detalles actuales de la FMCSA)." },
  { id: "gk-59", category: "general", topic: "Llave", q: "Durante la prueba de inspección del vehículo, ¿por qué poner la llave del interruptor de arranque en el bolsillo?", choices: ["Para que nadie pueda mover el vehículo mientras usted está debajo o alrededor de él", "Para drenar los tanques de aire", "Para desactivar el ABS", "Es solo un hábito para la Clase C"], a: 0, why: "Guarde la llave para que el vehículo no pueda arrancarse mientras usted inspecciona alrededor o debajo de él." },
  { id: "gk-60", category: "general", topic: "Frenos hidráulicos", q: "¿Cómo se prueban los frenos hidráulicos para detectar fugas?", choices: ["Bombee 3 veces y luego mantenga presión firme por 5 segundos; el pedal no debe moverse", "Drene el cilindro maestro", "Conduzca a velocidad de carretera y pise el pedal de golpe", "Escuche el claxon"], a: 0, why: "El movimiento del pedal al mantener la presión indica una fuga u otro problema hidráulico." },

  { id: "ab-01", category: "airBrakes", topic: "Compresor", q: "¿Por qué un sistema de frenos de aire necesita un compresor de aire?", choices: ["Para enfriar el motor", "Para generar y mantener la presión de aire para los frenos", "Para alimentar los faros", "Para dirigir el camión"], a: 1, why: "El compresor bombea aire a los tanques de almacenamiento para que los frenos tengan presión para operar." },
  { id: "ab-02", category: "airBrakes", topic: "Regulador", q: "¿Qué controla el regulador del compresor de aire?", choices: ["La presión de las llantas", "La presión del aceite del motor", "Cuándo el compresor se conecta y se desconecta", "La altura de rodaje del tráiler"], a: 2, why: "El regulador deja de bombear en la desconexión (alrededor de 125 psi) y vuelve a arrancar en la conexión (alrededor de 100 psi)." },
  { id: "ab-03", category: "airBrakes", topic: "Regulador", q: "La presión de desconexión del regulador es típicamente alrededor de:", choices: ["55 psi", "85 psi", "125 psi (a menudo en un rango de 120–140 psi)", "200 psi"], a: 2, why: "Manual: la desconexión es alrededor de 125 psi, comúnmente 120–140 psi según el vehículo." },
  { id: "ab-04", category: "airBrakes", topic: "Regulador", q: "La presión de conexión del regulador es típicamente alrededor de:", choices: ["20 psi", "55 psi", "100 psi", "150 psi"], a: 2, why: "Cuando la presión del tanque baja a unos 100 psi, el regulador permite que el compresor vuelva a bombear." },
  { id: "ab-05", category: "airBrakes", topic: "Tanques", q: "Un propósito principal de los tanques de aire es:", choices: ["Almacenar aire presurizado", "Almacenar combustible", "Almacenar refrigerante", "Almacenar aceite del motor"], a: 0, why: "Los depósitos almacenan aire comprimido para tener suministro para frenar." },
  { id: "ab-06", category: "airBrakes", topic: "Drenaje", q: "¿Por qué deben drenarse los tanques de aire?", choices: ["Para quitar el agua y el aceite que pueden congelarse o dañar el sistema", "Para agregar presión de aire", "Para enfriar los tambores", "Para aumentar la desconexión del regulador"], a: 0, why: "El aire comprimido contiene agua y aceite. El agua puede congelar las válvulas en clima frío; el aceite y el agua dañan el sistema." },
  { id: "ab-07", category: "airBrakes", topic: "Válvula de seguridad", q: "La válvula de alivio de seguridad del primer tanque de aire suele estar calibrada para abrirse a unos:", choices: ["100 psi", "125 psi", "150 psi", "200 psi"], a: 2, why: "La válvula de seguridad protege el tanque de demasiada presión y típicamente se abre a 150 psi. Si se abre, algo está mal." },
  { id: "ab-08", category: "airBrakes", topic: "Aire bajo", q: "Una advertencia visible de baja presión de aire debe encenderse cuando la presión baja a:", choices: ["Entre 55 y 75 psi (antes de 55 psi)", "Exactamente 20 psi", "150 psi", "Solo después de que se apliquen los frenos de resorte"], a: 0, why: "La advertencia debe activarse entre 55 y 75 psi, y antes de que la presión baje de 55 psi." },
  { id: "ab-09", category: "airBrakes", topic: "Aire bajo", q: "Cuando la advertencia de aire bajo se enciende por primera vez, usted debe:", choices: ["Seguir conduciendo hasta la siguiente parada de camiones", "Detener el vehículo de forma segura mientras todavía tiene control de los frenos", "Bombear el pedal rápidamente para restaurar la presión", "Esperar a que los frenos de resorte se apliquen automáticamente"], a: 1, why: "No espere a la aplicación automática de los frenos de resorte. Deténgase de forma segura mientras todavía puede controlar los frenos." },
  { id: "ab-10", category: "airBrakes", topic: "Frenos de resorte", q: "Los frenos de resorte se usan para:", choices: ["Solo el frenado de servicio", "El estacionamiento y el frenado de emergencia", "Enfriar los tambores", "Dirigir"], a: 1, why: "Resortes potentes aplican los frenos de estacionamiento/emergencia cuando se libera el aire. La presión de aire retiene los resortes mientras conduce." },
  { id: "ab-11", category: "airBrakes", topic: "Frenos de resorte", q: "Los frenos de resorte del tractocamión y del camión rígido típicamente se aplican por completo cuando la presión de aire baja a unos:", choices: ["100 psi", "75 psi", "20 a 45 psi (a menudo 20 a 30 psi)", "150 psi"], a: 2, why: "Cuando la presión cae al rango de 20–45 psi, se aplican los frenos de resorte. Deténgase antes de que eso ocurra." },
  { id: "ab-12", category: "airBrakes", topic: "Frenos de resorte", q: "¿Por qué nunca debe pisar el pedal del freno mientras los frenos de resorte están aplicados?", choices: ["Puede dañar los frenos al combinar la fuerza del resorte y la fuerza de aplicación por aire", "Aumenta el uso de combustible", "Apaga el ABS de forma permanente", "Drene el tanque de combustible"], a: 0, why: "Las fuerzas combinadas del resorte y del aire pueden dañar los componentes de los frenos. No pise el pedal con los resortes de estacionamiento aplicados." },
  { id: "ab-13", category: "airBrakes", topic: "Control de estacionamiento", q: "En los vehículos más nuevos, el control del freno de estacionamiento es:", choices: ["Una perilla octagonal roja", "Una perilla amarilla con forma de diamante de empujar-jalar: jálela para aplicar, empújela para soltar", "Un interruptor redondo azul en el piso", "Solo la válvula de mano del tráiler"], a: 1, why: "Perilla amarilla de diamante = frenos de estacionamiento. Jalar aplica; empujar suelta." },
  { id: "ab-14", category: "airBrakes", topic: "Retraso del freno", q: "El retraso del freno es:", choices: ["La demora entre pisar el pedal y que los frenos actúen, debido a que el aire se mueve por el sistema", "La demora de arranque del motor", "La demora del cambio de marcha", "La demora del acoplamiento del tráiler"], a: 0, why: "El aire tarda en fluir a las cámaras. Esa distancia extra es el retraso del freno, exclusivo de los frenos de aire en comparación con los hidráulicos." },
  { id: "ab-15", category: "airBrakes", topic: "Distancia de detención", q: "La distancia total de detención con frenos de aire incluye:", choices: ["Solo la distancia de percepción", "Percepción, reacción, retraso del freno y distancia de frenado", "Solo la distancia de frenado", "Solo la distancia de seguimiento"], a: 1, why: "La distancia de detención con frenos de aire suma percepción + reacción + retraso del freno + distancia de frenado." },
  { id: "ab-16", category: "airBrakes", topic: "ABS", q: "El ABS ayuda a prevenir:", choices: ["El exceso de revoluciones del motor", "El bloqueo de las ruedas durante un frenado fuerte para que pueda mantener el control de la dirección", "Todas las fugas de aire", "La necesidad de distancia de seguimiento"], a: 1, why: "El ABS reduce el bloqueo. No garantiza paradas más cortas ni le permite conducir más rápido." },
  { id: "ab-17", category: "airBrakes", topic: "ABS", q: "¿El ABS le permite conducir más rápido o seguir más de cerca en caminos resbaladizos?", choices: ["Sí, siempre", "Sí, si va cargado", "No", "Solo con un tráiler"], a: 2, why: "Manual: el ABS no le permitirá conducir más rápido, seguir más de cerca ni conducir con menos cuidado." },
  { id: "ab-18", category: "airBrakes", topic: "ABS", q: "Si el ABS se activa, usted generalmente debe:", choices: ["Bombear los frenos", "Mantener presión firme y constante en el pedal", "Soltar todo el frenado y dejar que ruede", "Aplicar el freno de estacionamiento"], a: 1, why: "No bombee el ABS. Mantenga presión firme y dirija. El ABS pulsa más rápido de lo que usted puede bombear." },
  { id: "ab-19", category: "airBrakes", topic: "Lámparas ABS", q: "Una lámpara amarilla de ABS que permanece encendida después de la prueba de bombillas significa:", choices: ["El ABS funciona perfectamente", "Puede haber perdido el control ABS en una o más ruedas; todavía tiene frenos normales", "El compresor de aire ha fallado", "Los frenos de resorte están aplicados"], a: 1, why: "Una lámpara que permanece encendida o se enciende al conducir indica una falla del ABS. Los frenos normales siguen funcionando; haga revisar el ABS." },
  { id: "ab-20", category: "airBrakes", topic: "Sistema dual", q: "Un sistema dual de frenos de aire es:", choices: ["Dos sistemas separados de frenos de aire que comparten un conjunto de controles", "Dos volantes", "Un sistema solo del tráiler", "Un sistema sin frenos de resorte"], a: 0, why: "Los sistemas primario y secundario tienen sus propios tanques y líneas, pero un pedal de freno. Si uno falla, el otro todavía puede frenar." },
  { id: "ab-21", category: "airBrakes", topic: "Sistema dual", q: "Antes de conducir un sistema de aire dual, genere por lo menos ¿cuánta presión en los sistemas primario y secundario?", choices: ["55 psi", "75 psi", "100 psi", "150 psi"], a: 2, why: "Deje que el compresor genere un mínimo de 100 psi en ambos sistemas antes de conducir." },
  { id: "ab-22", category: "airBrakes", topic: "Válvula de retención", q: "Una válvula de retención de un solo sentido entre el compresor y el primer tanque:", choices: ["Deja que el aire fluya solo hacia el tanque para que una fuga del compresor no vacíe los tanques", "Drene el agua automáticamente", "Aplica los frenos de resorte", "Conecta el regulador"], a: 0, why: "La válvula de retención impide que el aire almacenado se escape de vuelta por un compresor fallido." },
  { id: "ab-23", category: "airBrakes", topic: "Ajustadores de holgura", q: "Si jala un ajustador de holgura y se mueve más de aproximadamente una pulgada donde se une la varilla de empuje, el freno:", choices: ["Está perfecto", "Probablemente necesita ajuste o tiene un problema mecánico", "Tiene muy poca holgura", "Es una falla del ABS"], a: 1, why: "Más de aproximadamente 1 pulgada de movimiento significa que el freno está desajustado o que el ajustador automático/freno de base tiene un problema." },
  { id: "ab-24", category: "airBrakes", topic: "Balatas", q: "Las balatas de freno no deben estar desgastadas a menos de aproximadamente:", choices: ["1/8 de pulgada", "1/4 de pulgada", "1/2 pulgada", "1 pulgada"], a: 1, why: "Las balatas no deben estar sueltas, empapadas de aceite ni peligrosamente delgadas (menos de 1/4 de pulgada)." },
  { id: "ab-25", category: "airBrakes", topic: "Tambores", q: "Los tambores o discos de freno no deben tener grietas más largas que:", choices: ["Todo el ancho del tambor", "La mitad del ancho del área de fricción", "1 pulgada sin importar el tamaño", "Las grietas siempre son legales"], a: 1, why: "Las grietas más largas que la mitad del ancho del área de fricción son un defecto. También busque sobrecalentamiento y piezas sueltas." },
  { id: "ab-26", category: "airBrakes", topic: "Fuga aplicada", q: "En la prueba de fugas aplicada (retención de 1 minuto) para un vehículo sencillo, la pérdida máxima de aire es:", choices: ["2 psi", "3 psi", "4 psi", "6 psi"], a: 1, why: "Fuga aplicada: 3 psi/minuto vehículo sencillo; 4 psi combinación de 2; 6 psi combinación de 3 o más." },
  { id: "ab-27", category: "airBrakes", topic: "Fuga aplicada", q: "En la prueba de fugas aplicada para una combinación de dos vehículos con frenos de aire en ambas unidades, la pérdida máxima es:", choices: ["2 psi en 1 minuto", "3 psi en 1 minuto", "4 psi en 1 minuto", "10 psi en 1 minuto"], a: 2, why: "Combinación de 2 vehículos: 4 psi en 1 minuto con el freno de servicio aplicado." },
  { id: "ab-28", category: "airBrakes", topic: "Fuga estática", q: "En la prueba de fugas estáticas (frenos sueltos) para un vehículo sencillo, la pérdida máxima es:", choices: ["2 psi en 1 minuto", "3 psi en 1 minuto", "4 psi en 1 minuto", "6 psi en 1 minuto"], a: 0, why: "Estática: 2 psi sencillo; 3 psi combinación de 2; 5 psi combinación de 3+." },
  { id: "ab-29", category: "airBrakes", topic: "Acumulación", q: "En los sistemas de aire duales, la presión debe subir de unos 85 a 100 psi en:", choices: ["10 segundos", "45 segundos", "3 minutos", "10 minutos"], a: 1, why: "En ralentí normal, los sistemas duales deben pasar de unos 85 a 100 psi en 45 segundos." },
  { id: "ab-30", category: "airBrakes", topic: "Acumulación", q: "En los sistemas de aire sencillos más antiguos, la presión debe subir de unos 50 a 90 psi en:", choices: ["45 segundos", "90 segundos", "3 minutos", "10 minutos"], a: 2, why: "Sistemas sencillos anteriores a 1975: 50–90 psi en 3 minutos. Las revisiones en cabina de la prueba de destrezas también citan 50–90 en 3 minutos como norma de acumulación en algunos vehículos." },
  { id: "ab-31", category: "airBrakes", topic: "Prueba de aire bajo", q: "Para probar la advertencia de aire bajo, reduce la presión bombeando. La advertencia debe activarse antes de que la presión baje de:", choices: ["20 psi", "55 psi", "100 psi", "125 psi"], a: 1, why: "Verbalice que el dispositivo debe funcionar a no menos de 55 psi (típicamente 55–75 psi)." },
  { id: "ab-32", category: "airBrakes", topic: "Leva en S", q: "El freno de base más común en vehículos pesados es el:", choices: ["Freno de tambor de leva en S", "Solo freno eléctrico del tráiler", "Palanca de mano del freno de estacionamiento", "Freno del motor"], a: 0, why: "Los frenos de leva en S son los más comunes. El aire empuja una varilla, el ajustador de holgura gira el árbol de levas y la leva en S abre las zapatas." },
  { id: "ab-33", category: "airBrakes", topic: "Válvula limitadora delantera", q: "Si un vehículo tiene una válvula limitadora de frenos delanteros marcada Normal/Resbaladizo, usted debe:", choices: ["Usar Resbaladizo con lluvia para cortar a la mitad el aire de los frenos delanteros", "Mantenerla en Normal; los frenos de las ruedas delanteras son buenos en todas las condiciones", "Quitarlas", "Usar Resbaladizo en pavimento seco"], a: 1, why: "La posición Resbaladizo reduce la potencia de detención. Las pruebas muestran que los derrapes de los frenos delanteros son poco probables incluso en hielo. Use Normal." },
  { id: "ab-34", category: "airBrakes", topic: "Bombeo", q: "Bombear repetidamente el pedal del freno cuando la presión de aire ya está baja puede:", choices: ["Restaurar la presión del tanque", "Agotar el aire restante de modo que tenga aún menos frenado", "Cargar el compresor más rápido", "Soltar los frenos de resorte"], a: 1, why: "Cada aplicación usa aire. Bombear un sistema bajo puede agotar el poco aire que le queda." },
  { id: "ab-35", category: "airBrakes", topic: "Manómetro de aplicación", q: "Un manómetro de presión de aplicación muestra:", choices: ["La presión de las llantas", "Cuánta presión de aire está aplicando a los frenos", "La presión del aceite del motor", "El nivel de combustible"], a: 1, why: "Si necesita más presión de aplicación para mantener la misma velocidad cuesta abajo, los frenos se están desvaneciendo." },
  { id: "ab-36", category: "airBrakes", topic: "Evaporador de alcohol", q: "Algunos sistemas de aire tienen un evaporador de alcohol para:", choices: ["Aumentar la potencia", "Introducir alcohol en el sistema para reducir el riesgo de hielo en clima frío", "Limpiar el parabrisas", "Lubricar las levas en S automáticamente"], a: 1, why: "El alcohol puede ayudar a prevenir hielo en el sistema de aire. Los tanques igual deben drenarse; el evaporador es protección extra en algunos vehículos." },
  { id: "ab-37", category: "airBrakes", topic: "Prueba de servicio", q: "Durante una prueba de frenos de servicio en movimiento a unos 5 mph, usted busca:", choices: ["Que jale hacia un lado, una sensación inusual o una detención demorada", "Mejor recepción de radio", "RPM más altas", "Que la lámpara ABS parpadee como requisito para aprobar"], a: 0, why: "Una aplicación firme a baja velocidad revela jalón, demora o una sensación extraña que podría no notar hasta una emergencia." },
  { id: "ab-38", category: "airBrakes", topic: "Prueba de estacionamiento", q: "Para probar el freno de estacionamiento:", choices: ["Póngalo y jale suavemente contra él en una marcha baja", "Conduzca a 55 mph y jale la perilla de golpe", "Drene todos los tanques primero", "Pise el pedal con los resortes aplicados"], a: 0, why: "Cinturón puesto, freno de estacionamiento aplicado, un jalón suave en marcha baja para confirmar que sostiene." },
  { id: "ab-39", category: "airBrakes", topic: "Frenado intermitente", q: "El frenado intermitente (stab) solo debe usarse:", choices: ["En vehículos con ABS funcionando en todos los ejes", "En vehículos sin ABS, aplicando a fondo, soltando cuando las ruedas se bloquean y volviendo a aplicar cuando ruedan", "En lugar de un freno de estacionamiento", "Para drenar los tanques"], a: 1, why: "El frenado intermitente es un método de emergencia sin ABS. Con ABS, mantenga presión firme en lugar de bombear o aplicar de forma intermitente." },
  { id: "ab-40", category: "airBrakes", topic: "Fechas requeridas de ABS", q: "Los tractocamiones con frenos de aire fabricados a partir de ¿qué fecha deben tener ABS?", choices: ["1 de marzo de 1997", "1 de marzo de 2005", "1 de enero de 1980", "Solo 2020 y más nuevos"], a: 0, why: "Tractocamiones: 1 de marzo de 1997. Otros vehículos con frenos de aire, incluidos tráileres/dollies: 1 de marzo de 1998." },
  { id: "ab-41", category: "airBrakes", topic: "Wig-wag", q: "Un wig-wag es:", choices: ["Un tipo de quinta rueda", "Un brazo de advertencia de aire bajo que cae a la vista del conductor", "Un sello de conector de aire", "Un freno del motor"], a: 1, why: "Algunos vehículos usan un brazo mecánico (wig-wag) como advertencia visible de aire bajo en el rango de 55–75 psi." },
  { id: "ab-42", category: "airBrakes", topic: "Ajustadores automáticos", q: "Si los ajustadores automáticos de holgura están desajustados, usted debe:", choices: ["Apretarlos rutinariamente todos los días como mantenimiento normal", "Llevar el vehículo a reparación; el ajuste manual generalmente solo oculta un problema mecánico", "Ignorarlos porque son automáticos", "Quitarlos"], a: 1, why: "El ajuste manual de los ajustadores automáticos es solo una medida de emergencia temporal. El problema de fondo debe repararse." },
  { id: "ab-43", category: "airBrakes", topic: "Parada normal", q: "En una parada normal con transmisión manual, usted debe:", choices: ["Pisar el clutch de inmediato al empezar a frenar", "Controlar la presión del pedal para una parada suave y no pisar el clutch hasta que las RPM del motor estén cerca del ralentí", "Pasar a reversa", "Usar solo la válvula de mano del tráiler"], a: 1, why: "Mantenga el motor conectado para control y efecto de frenado hasta que las RPM bajen cerca del ralentí; luego pise el clutch y seleccione una marcha de arranque." },
  { id: "ab-44", category: "airBrakes", topic: "Banda", q: "Si el compresor de aire es impulsado por banda, durante la inspección previa al viaje debe revisar:", choices: ["La condición y la tensión de la banda", "Solo el color de la pintura", "Solo el claxon", "Solo los sellos de la carga"], a: 0, why: "Una banda del compresor suelta o dañada puede impedir que el sistema genere aire." },
  { id: "ab-45", category: "airBrakes", topic: "Mangueras", q: "Las mangueras de aire hacia las cámaras de freno deben estar:", choices: ["Cortadas y rozadas para que flexionen más", "Libres de cortes, desgaste por roce, fugas y conexiones deficientes", "Cubiertas de grasa", "Desconectadas al conducir"], a: 1, why: "Las mangueras dañadas fugan aire y pueden causar falla de los frenos. Inspeccione durante el recorrido alrededor del vehículo." },

  { id: "cv-01", category: "combination", topic: "Definición", q: "Un vehículo combinado es:", choices: ["Cualquier camión con aire acondicionado", "Una unidad motriz acoplada a uno o más tráileres", "Un autobús con pasajeros de pie", "Una camioneta de menos de 10,000 libras"], a: 1, why: "Combinación significa tractocamión-semirremolque o combinaciones camión-tráiler." },
  { id: "cv-02", category: "combination", topic: "Quinta rueda", q: "El dispositivo que conecta un tractocamión a un semirremolque es la:", choices: ["Quinta rueda", "Columna de dirección", "Cámara de freno", "Solo el gancho pintle"], a: 0, why: "La quinta rueda del tractocamión se cierra alrededor del perno rey del tráiler." },
  { id: "cv-03", category: "combination", topic: "Perno rey", q: "El perno rey es:", choices: ["El seguro del volante", "El perno del tráiler que se cierra en las mandíbulas de la quinta rueda", "El pedal de freno del tráiler", "El sello del conector de aire"], a: 1, why: "Las mandíbulas deben cerrarse en el vástago del perno rey, no en la cabeza." },
  { id: "cv-04", category: "combination", topic: "Grasa", q: "¿Por qué debe engrasarse la placa de la quinta rueda según se requiera?", choices: ["Para reducir la fricción entre el tractocamión y el tráiler; la falta de grasa puede causar problemas de dirección", "Para mejorar el volumen del claxon", "Para subir la presión de aire", "Para apretar las tuercas de las ruedas"], a: 0, why: "Una quinta rueda sin lubricar puede trabarse y dificultar la dirección." },
  { id: "cv-05", category: "combination", topic: "Antes de acoplar", q: "Antes de acoplar, la quinta rueda debe estar:", choices: ["Inclinada hacia abajo hacia la parte trasera del tractocamión, mandíbulas abiertas, palanca de desbloqueo en la posición de cierre automático", "Inclinada hacia arriba hacia la cabina con las mandíbulas cerradas", "Retirada", "Cubierta para que no pueda ver las mandíbulas"], a: 0, why: "La inclinación correcta y las mandíbulas abiertas permiten que el perno rey entre y se cierre. Las quintas ruedas deslizantes deben estar bloqueadas." },
  { id: "cv-06", category: "combination", topic: "Alineación", q: "¿Por qué el tractocamión debe estar alineado en línea recta con el tráiler antes de acoplar?", choices: ["Entrar en reversa en ángulo puede empujar el tráiler hacia un lado y romper las patas de apoyo", "Aumenta las RPM del motor", "Drene los tanques de aire", "Es solo por apariencia"], a: 0, why: "Nunca entre en reversa en ángulo. Un acoplamiento torcido daña las patas de apoyo y puede fallar el cierre." },
  { id: "cv-07", category: "combination", topic: "Altura", q: "La altura del tráiler antes de acoplar debe ser:", choices: ["Mucho más alta que la quinta rueda para que caiga encima", "Ligeramente más baja que el centro de la quinta rueda para que el tráiler se levante un poco al entrar en reversa", "Exactamente a la altura del techo de la cabina", "Apoyada en los rieles del chasis"], a: 1, why: "Una altura del tráiler ligeramente baja permite que la quinta rueda levante el tráiler y complete un acoplamiento sólido." },
  { id: "cv-08", category: "combination", topic: "Prueba de tirón", q: "Después de acoplar, una prueba de tirón se usa para:", choices: ["Calentar las llantas", "Confirmar que la quinta rueda está cerrada jalando suavemente contra los frenos del tráiler", "Drenar los tanques", "Fijar la temperatura de la carga"], a: 1, why: "Con los frenos del tráiler puestos, avance con suavidad. Si el acoplamiento es malo, se saldrá en lugar de remolcar el tráiler." },
  { id: "cv-09", category: "combination", topic: "Cierre visual", q: "Después de acoplar debe mirar por la parte trasera de la quinta rueda para confirmar:", choices: ["Que hay una holgura grande", "Que las mandíbulas de cierre están cerradas alrededor del vástago del perno rey y no hay espacio entre la quinta rueda superior e inferior", "Que el perno rey está sentado encima de las mandíbulas cerradas", "Que las mandíbulas siguen abiertas"], a: 1, why: "Un espacio puede significar que el perno rey está encima de las mandíbulas cerradas: el tráiler puede desprenderse. Las mandíbulas deben estar en el vástago." },
  { id: "cv-10", category: "combination", topic: "Patas de apoyo", q: "Antes de conducir, las patas de apoyo deben estar:", choices: ["Levantadas por completo con la manivela asegurada", "Dejadas a media altura para estabilidad", "Apoyadas en el pavimento", "Retiradas"], a: 0, why: "Las patas a media altura pueden engancharse en vías o pavimento. Levántelas por completo y guarde la manivela." },
  { id: "cv-11", category: "combination", topic: "Levantar patas de apoyo", q: "Al levantar las patas de apoyo después de acoplar:", choices: ["Use marcha baja hasta que queden libres de peso, luego marcha alta, y levántelas por completo", "Quédese siempre en marcha alta con todo el peso del tráiler", "Déjelas 6 pulgadas abajo", "Levántelas solo hasta que apenas despejen el suelo"], a: 0, why: "La marcha baja inicia el levantamiento bajo carga; la marcha alta termina cuando ya no hay peso. Levántelas hasta el tope." },
  { id: "cv-12", category: "combination", topic: "Líneas de aire", q: "Después de acoplar, ¿qué conexiones deben asegurarse?", choices: ["El cable eléctrico y las líneas de aire (conectores glad hands)", "Los limpiaparabrisas", "Solo la tapa del combustible", "Solo el espejo del pasajero"], a: 0, why: "Los conectores glad hands y la conexión eléctrica de 7 vías (o equivalente) deben estar cerrados, sostenidos y sin fugas." },
  { id: "cv-13", category: "combination", topic: "Colores", q: "Las líneas de aire de emergencia (suministro) a menudo están codificadas por color ____; las de servicio ____.", choices: ["Azul; rojo", "Rojo; azul", "Amarillo; verde", "Blanco; negro"], a: 1, why: "Rojo = emergencia/suministro. Azul = servicio/control. Cruzarlas es peligroso." },
  { id: "cv-14", category: "combination", topic: "Líneas cruzadas", q: "Si cruza las líneas de aire en un tráiler más nuevo con frenos de resorte:", choices: ["No pasa nada", "El aire de suministro va a la línea de servicio; los frenos de resorte del tráiler pueden no soltarse", "El tractocamión va más rápido", "El ABS se apaga de forma permanente"], a: 1, why: "Las líneas cruzadas pueden mantener aplicados los resortes de estacionamiento del tráiler. Si los resortes no se sueltan cuando empuja la perilla de suministro, revise las conexiones." },
  { id: "cv-15", category: "combination", topic: "Tráileres antiguos", q: "Si cruza las líneas de aire en un tráiler más antiguo sin frenos de resorte:", choices: ["Puede poder irse sin frenos del tráiler: muy peligroso", "El tráiler no puede rodar", "La válvula de protección del tractor desaparece", "El perno rey se funde"], a: 0, why: "Sin frenos de resorte, un enganche cruzado puede dejar los frenos del tráiler inoperantes mientras las ruedas giran libremente." },
  { id: "cv-16", category: "combination", topic: "Conectores glad hands", q: "Para acoplar los conectores glad hands usted debe:", choices: ["Presionar los sellos juntos a unos 90 grados y luego girar para cerrar", "Clavarlos a martillazos", "Conectar rojo con azul", "Dejar uno desacoplado para el ABS"], a: 0, why: "Sellos limpios, unión a 90 grados y luego girar para cerrar. Sostenga las mangueras para que no arrastren ni se enganchen." },
  { id: "cv-17", category: "combination", topic: "Perilla de suministro", q: "El control de suministro de aire del tráiler en los vehículos más nuevos es:", choices: ["Un diamante amarillo", "Una perilla roja de ocho lados: empújela para suministrar al tráiler, jálela para cortar el aire y aplicar los frenos de emergencia del tráiler", "El botón del claxon", "El interruptor de los faros"], a: 1, why: "Octágono rojo = protección del tractor / suministro de aire del tráiler. Debe salir alrededor de 20–45 psi si se pierde la presión." },
  { id: "cv-18", category: "combination", topic: "Protección del tractor", q: "La válvula de protección del tractor:", choices: ["Impide que el tractocamión pierda todo el aire si el tráiler se desprende o falla una línea de aire del tráiler", "Dirige el tráiler", "Engrasa la quinta rueda", "Carga las baterías"], a: 0, why: "Cierra las líneas de aire hacia el tráiler para proteger el suministro de aire del tractocamión." },
  { id: "cv-19", category: "combination", topic: "Desviación de trayectoria", q: "La desviación de trayectoria del tráiler significa:", choices: ["Las ruedas del tráiler siguen una trayectoria más corta que las ruedas del tractocamión en un giro", "El tráiler rebasa al tractocamión", "El tráiler no tiene luces", "El tráiler está vacío"], a: 0, why: "Las ruedas traseras toman una trayectoria más corta. Debe girar lo suficientemente amplio para que el tráiler no suba a las banquetas ni golpee vehículos." },
  { id: "cv-20", category: "combination", topic: "Giros", q: "Debe girar amplio en una combinación debido a:", choices: ["La desviación de trayectoria", "El mayor uso de combustible en un giro amplio", "Las reglas del ABS", "La grasa del perno rey"], a: 0, why: "La desviación de trayectoria requiere una trayectoria más amplia. No se abra hacia otros carriles más de lo necesario." },
  { id: "cv-21", category: "combination", topic: "Navaja", q: "Una navaja es:", choices: ["El tractocamión y el tráiler plegándose uno hacia el otro", "Un método de inflado de llantas", "Una cincha de carga", "Un tipo de triángulo"], a: 0, why: "El bloqueo de las ruedas del tráiler es una causa común de navaja del tráiler. El bloqueo de las ruedas motrices puede causar una navaja del tractocamión." },
  { id: "cv-22", category: "combination", topic: "Navaja", q: "Los tráileres vacíos o con poca carga se pliegan en navaja más fácilmente porque:", choices: ["Tienen menos peso y tracción en las ruedas del tráiler, así que esos frenos pueden bloquearse antes", "Tienen frenos más fuertes que los tráileres cargados en todos los casos", "No pueden girar", "No tienen lámparas ABS"], a: 0, why: "Los ejes livianos del tráiler se bloquean más fácilmente. Frene con suavidad y nunca aplique de golpe solo los frenos del tráiler en caminos resbaladizos." },
  { id: "cv-23", category: "combination", topic: "Válvula de mano", q: "La válvula de mano del tráiler (válvula trolley) no debe usarse para:", choices: ["Probar los frenos del tráiler o evitar que retroceda en algunos arranques", "Estacionar, porque el aire puede fugarse", "Una prueba de tirón", "Una revisión suave de los frenos del tráiler"], a: 1, why: "No use la válvula de mano para sostener un vehículo estacionado. El aire puede fugarse y el vehículo puede rodar. Use los frenos de estacionamiento." },
  { id: "cv-24", category: "combination", topic: "Volcadura", q: "La forma más segura de prevenir una volcadura de una combinación es:", choices: ["Reducir la velocidad antes de las curvas y las rampas de entrada/salida", "Frenar con fuerza en cada giro", "Cambiar de marcha en la curva", "Girar lo más cerrado posible"], a: 0, why: "Más de la mitad de las volcaduras de tractocamión-tráiler se relacionan con velocidad excesiva en curvas. Un CG alto empeora esto." },
  { id: "cv-25", category: "combination", topic: "Centro de gravedad", q: "Un centro de gravedad alto:", choices: ["Reduce el riesgo de volcadura", "Aumenta el riesgo de volcadura", "Elimina la desviación de trayectoria", "Acorta legalmente la distancia de seguimiento"], a: 1, why: "Las cargas con mucho peso arriba se vuelcan más fácilmente. Mantenga la carga baja y reduzca antes de los giros." },
  { id: "cv-26", category: "combination", topic: "Desacoplar", q: "Al desacoplar, después de sacar el tractocamión en parte debe detenerse con el chasis del tractocamión todavía debajo del tráiler porque:", choices: ["Se ve profesional", "Si las patas de apoyo se hunden o se colapsan, el chasis del tractocamión todavía puede sostener el tráiler", "Carga el ABS", "Engrasa el perno rey"], a: 1, why: "Nunca salga por completo de una vez. Pause con el chasis debajo del tráiler como apoyo de seguridad." },
  { id: "cv-27", category: "combination", topic: "Presión al desacoplar", q: "Para aliviar la presión en las mandíbulas de cierre de la quinta rueda antes de desacoplar:", choices: ["Retroceda con suavidad y luego ponga los frenos de estacionamiento mientras empuja contra el perno rey", "Aléjese a velocidad de carretera", "Levante el tráiler de la quinta rueda con las patas de apoyo", "Desconecte la batería"], a: 0, why: "Retroceder con suavidad quita carga de las mandíbulas para poder jalar la palanca de liberación." },
  { id: "cv-28", category: "combination", topic: "Desacoplar con carga", q: "Al bajar las patas de apoyo en un tráiler cargado para desacoplar:", choices: ["Bájelas hasta un contacto firme y luego unas cuantas vueltas extra en marcha baja para quitar algo de peso del tractocamión: no levante el tráiler de la quinta rueda", "Levante el tráiler por completo de la quinta rueda", "Deje las patas arriba", "Ponga las patas solo en un acotamiento blando"], a: 0, why: "Un poco de manivela extra descarga el tractocamión ligeramente. Levantar de la quinta rueda es incorrecto y peligroso." },
  { id: "cv-29", category: "combination", topic: "Acopladores ficticios", q: "Los conectores glad hands deben ponerse en acopladores ficticios o acoplarse entre sí cuando no se usan para:", choices: ["Mantener el agua y la suciedad fuera de las líneas", "Aumentar la presión", "Desactivar los frenos de resorte", "Cargar el cable eléctrico"], a: 0, why: "Los acopladores ficticios (de extremo muerto) protegen los sellos y evitan la contaminación del sistema de aire." },
  { id: "cv-30", category: "combination", topic: "Sostener las líneas", q: "Las líneas de aire y eléctricas deben sostenerse para que:", choices: ["No puedan arrastrarse, engancharse ni aplastarse en un giro", "Queden tensas sin holgura", "Cuelguen en el suelo para enfriarse", "Estén atadas a una llanta"], a: 0, why: "Suficiente holgura para los giros, pero no tanta que rocen o se enganchen." },
  { id: "cv-31", category: "combination", topic: "Despeje", q: "Después de que el peso del tráiler está sobre el tractocamión, revise el despeje para que en un giro cerrado:", choices: ["El chasis del tractocamión no golpee las patas de apoyo y las llantas no golpeen la nariz del tráiler", "La antena de la radio despeje la carga", "La quinta rueda esté seca", "La perilla de suministro esté jalada"], a: 0, why: "El golpe a las patas de apoyo y el contacto cabina/tráiler son puntos de inspección del acoplamiento, especialmente con una quinta rueda deslizante demasiado adelante." },
  { id: "cv-32", category: "combination", topic: "Quinta rueda deslizante", q: "Una quinta rueda deslizante debe tener:", choices: ["Todos los pernos de cierre en su lugar y el deslizamiento bloqueado; no tan adelante que el chasis golpee las patas de apoyo en los giros", "Los pernos retirados para flexibilidad", "Sin grasa", "Mandíbulas abiertas al conducir"], a: 0, why: "Los deslizamientos sin bloqueo pueden moverse bajo el tráiler. La posición afecta la distribución del peso y el despeje en los giros." },
  { id: "cv-33", category: "combination", topic: "Probar frenos del tráiler", q: "Siempre pruebe los frenos del tráiler antes de conducir:", choices: ["Usando la válvula de mano o jalando el control de suministro de aire y luego jalando suavemente contra ellos en marcha baja", "Tocando el claxon dos veces", "Apagando el motor", "Liberando todo el aire"], a: 0, why: "Confirme que el tráiler realmente tiene frenos antes de entrar al tráfico." },
  { id: "cv-34", category: "combination", topic: "ABS mixto", q: "Si solo el tractocamión tiene ABS:", choices: ["Aun así debe frenar de forma normal; puede mantener la dirección, pero vigile el tráiler y suelte si se sale", "Debe bombear los frenos", "Los frenos del tráiler no funcionarán", "Puede conducir más rápido en las curvas"], a: 0, why: "El ABS parcial igual ayuda. Frene de forma normal. Si el tráiler se sale, suelte si es seguro." },
  { id: "cv-35", category: "combination", topic: "Latigazo", q: "La amplificación hacia atrás (“latigazo”) es más grave cuando:", choices: ["Hace un cambio de carril o un viraje súbito con una combinación, especialmente dobles", "Conduce despacio en línea recta", "La quinta rueda está engrasada", "El ABS está funcionando"], a: 0, why: "La unidad trasera puede balancearse mucho más que el tractocamión. Evite entradas de dirección abruptas." },
  { id: "cv-36", category: "combination", topic: "Seguimiento", q: "Las combinaciones necesitan más distancia de seguimiento que muchos camiones rígidos porque:", choices: ["Son más cortas", "A menudo necesitan más distancia de detención y tienen resultados de choque más graves si golpea a alguien", "No tienen frenos", "La desviación de trayectoria acorta las paradas"], a: 1, why: "El peso, el retraso de los frenos de aire y las múltiples unidades significan más espacio. Golpear un auto por detrás es un choque común y grave de CMV." },
  { id: "cv-37", category: "combination", topic: "Calzo", q: "Antes de acoplar o desacoplar, las ruedas deben calzarse si:", choices: ["Tiene alguna duda de que los frenos sostendrán el tráiler", "El tráiler está en un piso de taller perfectamente nivelado con frenos de resorte confirmados y nunca calza por hábito", "Está lloviendo", "El ABS está encendido"], a: 0, why: "Calce siempre que no esté seguro de que el tráiler no pueda rodar, especialmente los tráileres más antiguos sin frenos de resorte." },
  { id: "cv-38", category: "combination", topic: "Eléctrico", q: "El cable eléctrico del tráiler debe estar:", choices: ["Firmemente asentado, cerrado y sostenido con holgura para los giros", "Colgando en la pasarela", "Empalmado con cinta como método normal", "Desconectado al conducir para ahorrar bombillas"], a: 0, why: "Un conector de 7 vías suelto causa tráileres oscuros y problemas de comunicación del ABS. Inspecciónelo en cada acoplamiento." },
  { id: "cv-39", category: "combination", topic: "Inspección del perno rey", q: "Antes de acoplar, inspeccione el perno rey en busca de:", choices: ["Dobladuras, grietas o daños", "Solo el color de la pintura", "Grasa en la cabina", "Marca de las llantas"], a: 0, why: "Un perno rey doblado o roto puede impedir un cierre seguro." },
  { id: "cv-40", category: "combination", topic: "Seguro de seguridad", q: "Después de acoplar, el seguro / traba de seguridad de la quinta rueda debe estar:", choices: ["En posición sobre la palanca de cierre (algunos deben colocarse a mano)", "Dejado fuera para desacoplar más rápido", "Cableado abierto", "Engrasado cerrado para que no se mueva"], a: 0, why: "El seguro de seguridad impide que la palanca de liberación se abra en el camino." },

  { id: "dt-01", category: "doubles", topic: "Orden de peso", q: "Para el manejo más seguro de dobles, el tráiler más cargado debe ir:", choices: ["Atrás", "En la primera posición detrás del tractocamión", "Solo en el dolly", "Vacío"], a: 1, why: "El más pesado primero y el más liviano atrás reduce la inestabilidad y la amplificación hacia atrás." },
  { id: "dt-02", category: "doubles", topic: "Dolly", q: "Un dolly convertidor es:", choices: ["Un dispositivo de acoplamiento con quinta rueda usado para enganchar un segundo semirremolque", "Un tipo de freno del motor", "Un calentador de carga", "Un ajustador de holgura"], a: 0, why: "La quinta rueda del dolly acopla el semirremolque trasero; un gancho pintle conecta el dolly al tráiler delantero." },
  { id: "dt-03", category: "doubles", topic: "Frenos de resorte", q: "Los dollies convertidores:", choices: ["Siempre tienen frenos de resorte", "No están obligados a tener frenos de resorte, y muchos no los tienen", "Nunca tienen ruedas", "Reemplazan la válvula de protección del tractor"], a: 1, why: "Sepa cómo aplicar los frenos de emergencia o calzar un dolly/segundo tráiler que puede no tener resortes de estacionamiento." },
  { id: "dt-04", category: "doubles", topic: "Asegurar el segundo", q: "Si el segundo tráiler no tiene frenos de resorte, una forma de aplicar sus frenos de emergencia antes de acoplar es:", choices: ["Conectar la línea de emergencia, cargar el tanque y luego desconectar la línea de emergencia", "Llenar las llantas con agua", "Quitar los conectores glad hands de forma permanente", "Abrir las válvulas de cierre traseras"], a: 0, why: "Cargar y luego desconectar la línea de emergencia (suministro) aplica los frenos de emergencia en los tráileres que funcionan así. Calce si no está seguro." },
  { id: "dt-05", category: "doubles", topic: "Cierres", q: "Las válvulas de cierre deben estar:", choices: ["Cerradas en la parte trasera del último tráiler y abiertas en los demás", "Abiertas en todos los tráileres, incluido el último", "Cerradas solo en el primer tráiler", "Retiradas"], a: 0, why: "Las válvulas traseras del último tráiler cerradas para que el aire no se escape. Las válvulas intermedias abiertas para que el aire llegue a cada tráiler." },
  { id: "dt-06", category: "doubles", topic: "Pintle", q: "Al acoplar un dolly al tráiler delantero, el gancho pintle debe estar:", choices: ["Cerrado, con el apoyo del dolly levantado y asegurado cuando se requiera", "Dejado abierto para flexibilidad", "Cableado a una cámara de freno", "Engrasado en lugar de cerrado"], a: 0, why: "Un pintle sin cierre puede dejar caer el dolly. Inspeccione el gancho, el seguro de seguridad y el ojal." },
  { id: "dt-07", category: "doubles", topic: "Latigazo", q: "Los dobles y triples tienen más probabilidad de volcarse que un tráiler sencillo en parte por:", choices: ["La amplificación hacia atrás (latigazo)", "Tener demasiados espejos", "Un centro de gravedad más bajo", "Una distancia de detención siempre más corta"], a: 0, why: "Una dirección rápida en el tractocamión puede convertirse en un balanceo mucho mayor en el tráiler trasero." },
  { id: "dt-08", category: "doubles", topic: "California", q: "Las combinaciones de tráileres triples en carreteras públicas de California:", choices: ["Generalmente no son legales", "Se requieren para la Clase A", "Están permitidas en cada calle de la ciudad", "Son lo mismo que un tráiler sencillo de 53 pies"], a: 0, why: "California no permite tráileres triples. La endoso T igual importa si operará dobles aquí o triples en estados que los permiten." },
  { id: "dt-09", category: "doubles", topic: "Sacar el dolly", q: "¿Por qué sacar un dolly de debajo de un tráiler antes de desconectarlo del tráiler de adelante?", choices: ["El tráiler podría caer o el dolly podría plegarse en navaja/volcarse si sigue acoplado cuando la unidad delantera se aleja", "Ahorra grasa", "Lo exige el ABS", "Carga el segundo tráiler"], a: 0, why: "Desenganche en el orden correcto para que el tráiler trasero y el dolly permanezcan controlados y sostenidos." },
  { id: "dt-10", category: "doubles", topic: "Flujo de aire", q: "Puede probar que el aire fluye a todos los tráileres:", choices: ["Abriendo el cierre de la línea de emergencia trasera del último tráiler y escuchando/sintiendo el aire, y luego cerrándolo", "Tocando el claxon", "Mirando solo el medidor de combustible", "Desconectando el cable eléctrico"], a: 0, why: "Después de cargar, verifique que el aire llegue al último tráiler y luego cierre las últimas válvulas." },
  { id: "dt-11", category: "doubles", topic: "Altura del dolly", q: "Antes de acoplar un dolly a un segundo semirremolque, la altura del tráiler debe ser:", choices: ["Ligeramente más baja que la quinta rueda del dolly para que el tráiler se levante al empujar debajo", "Mucho más alta para que caiga", "Irrelevante", "Al nivel del techo del tractocamión"], a: 0, why: "El mismo principio que el acoplamiento del tractocamión: un ligero levantamiento al pasar la quinta rueda debajo." },
  { id: "dt-12", category: "doubles", topic: "Dirección", q: "Para reducir el riesgo de latigazo con dobles usted debe:", choices: ["Dirigir con suavidad y evitar cambios de carril súbitos", "Virar temprano y a menudo", "Frenar solo con la válvula de mano del último tráiler", "Viajar siempre vacío en el tráiler delantero"], a: 0, why: "Las entradas suaves evitan que el tráiler trasero amplifique el movimiento." },
  { id: "dt-13", category: "doubles", topic: "Marcha atrás", q: "Dar marcha atrás con dobles:", choices: ["Generalmente se evita; es más difícil que con un sencillo y a menudo requiere un vigilante y más espacio", "Es más fácil que dar marcha atrás con un camión rígido", "Es ilegal en todos los estados", "Se hace a velocidad de carretera"], a: 0, why: "Dos puntos de pivote hacen difícil dar marcha atrás con dobles. Evítelo; pida ayuda si debe hacerlo." },
  { id: "dt-14", category: "doubles", topic: "Inspeccionar el dolly", q: "Al inspeccionar un dolly convertidor, revise:", choices: ["Quinta rueda, ojal/gancho pintle, líneas de aire y eléctricas, ruedas/llantas y frenos", "Solo la pintura", "Solo la placa", "Solo los sellos de la carga"], a: 0, why: "El dolly es una unidad completa de acoplamiento y frenos. Inspecciónelo como un tráiler pequeño." },
  { id: "dt-15", category: "doubles", topic: "Navaja", q: "Los dobles tienen más probabilidad de plegarse en navaja que un tráiler sencillo porque:", choices: ["Hay más puntos de articulación y la unidad trasera es más liviana/móvil", "No tienen frenos", "Desaparece la desviación de trayectoria", "No pueden usar ABS"], a: 0, why: "Más bisagras y a menudo un tráiler trasero liviano aumentan el riesgo de navaja y latigazo." },

  { id: "tk-01", category: "tanker", topic: "Oleaje", q: "El oleaje del líquido es:", choices: ["El movimiento hacia adelante/atrás/a los lados del líquido en un tanque que puede empujar el vehículo", "Un tipo de ABS", "Un método de acoplamiento", "Solo hidroplaneo de las llantas"], a: 0, why: "Cuando frena, el líquido se lanza hacia adelante y puede empujar el tractocamión; al detenerse, puede golpear de nuevo. Se requiere una conducción suave." },
  { id: "tk-02", category: "tanker", topic: "Deflectores", q: "Los tanques con deflectores (baffles):", choices: ["Eliminan por completo el oleaje", "Tienen mamparos con orificios que ralentizan el oleaje pero no lo detienen", "Son ilegales en California", "Son solo para granel seco"], a: 1, why: "Los deflectores reducen el oleaje, especialmente de adelante hacia atrás, pero igual debe controlar el movimiento del líquido." },
  { id: "tk-03", category: "tanker", topic: "Ánima lisa", q: "Los tanques sin deflectores (ánima lisa):", choices: ["Tienen menos oleaje que los tanques con deflectores", "Son comunes para líquidos de grado alimenticio y tienen más oleaje, así que necesitan una conducción aún más suave", "No pueden volcarse", "No necesitan espacio vacío (outage)"], a: 1, why: "Los tanques sanitarios a menudo son lisos por dentro. El oleaje es peor. Conduzca como si la carga intentara seguir moviéndose." },
  { id: "tk-04", category: "tanker", topic: "Espacio vacío", q: "El espacio vacío (outage) es:", choices: ["El espacio vacío que se deja en un tanque para la expansión del líquido", "Un tipo de conector glad hand", "El retraso del freno", "La desviación de trayectoria"], a: 0, why: "Los líquidos se expanden con el calor. Nunca llene un tanque de carga por completo; deje el espacio vacío requerido." },
  { id: "tk-05", category: "tanker", topic: "Curvas", q: "Los vehículos cisterna tienen un centro de gravedad alto, así que usted debe:", choices: ["Tomar las curvas y rampas extra despacio", "Frenar con fuerza en cada curva", "Conducir más rápido cuando está a medio llenar", "Depender de los deflectores en lugar del control de velocidad"], a: 0, why: "Los tanques son inestables por el peso arriba. Los tanques a medio llenar también pueden tener más oleaje. Reduzca antes de la curva." },
  { id: "tk-06", category: "tanker", topic: "Frenado", q: "Para controlar el oleaje al detener una cisterna:", choices: ["Frene de forma suave y constante; no bloquee las ruedas", "Aplique frenado intermitente repetidamente como primera opción con ABS", "Use solo la válvula de mano del tráiler a velocidad de carretera", "Reduzca a reversa"], a: 0, why: "Una parada suave deja que el líquido se asiente. Las ruedas bloqueadas más el oleaje pueden causar navaja o sacarlo de su carril." },
  { id: "tk-07", category: "tanker", topic: "Mamparos", q: "Los mamparos en un tanque:", choices: ["Dividen el tanque en compartimentos, lo que puede reducir el oleaje, pero cada compartimento igual olea", "Eliminan la necesidad de un CDL", "Son lo mismo que las llantas", "Eliminan las reglas de espacio vacío"], a: 0, why: "Los tanques compartimentados igual necesitan una conducción cuidadosa; una carga desigual de los compartimentos también afecta el manejo." },
  { id: "tk-08", category: "tanker", topic: "Definición", q: "Un endoso de vehículo cisterna generalmente se requiere para tanques con:", choices: ["Una capacidad individual de más de 119 galones y una capacidad agregada de 1,000 galones o más, unidos de forma permanente o temporal", "Cualquier botella de agua", "Solo tanques de diésel laterales en un tractocamión", "Solo latas portátiles de 5 galones"], a: 0, why: "El endoso N cubre tanques de carga grandes/tanques portátiles que cumplen esas reglas de capacidad (los contenedores de almacenamiento vacíos diseñados para transporte también tienen reglas)." },
  { id: "tk-09", category: "tanker", topic: "Derrape", q: "Si siente que una cisterna empieza a derrapar por el oleaje, usted debe:", choices: ["Dirigir y contradirigir con suavidad y soltar los frenos si las ruedas se bloquean (a menos que use ABS según el entrenamiento)", "Acelerar con fuerza", "Aplicar los frenos de estacionamiento", "Girar más cerrado"], a: 0, why: "Recupere primero el rodamiento y la dirección. Un frenado extra súbito puede empeorar el oleaje." },
  { id: "tk-10", category: "tanker", topic: "Inspección", q: "Antes de cargar o conducir un tanque de carga, inspeccione:", choices: ["Bocas de hombre, válvulas, tuberías y empaques por fugas y que las tapas estén seguras", "Solo la radio", "Solo la grasa de la quinta rueda", "Solo el claxon"], a: 0, why: "Las válvulas con fugas o las tapas de boca de hombre sueltas pueden derramar producto. Revise también después de cargar." },
  { id: "tk-11", category: "tanker", topic: "Curvas vacía", q: "Un vehículo cisterna vacío igual necesita precaución en las curvas porque:", choices: ["El cuerpo alto del tanque todavía tiene un centro de gravedad relativamente alto comparado con muchos furgones secos", "Los tanques vacíos no pueden volcarse", "El ABS no funciona vacío", "El espacio vacío se vuelve negativo"], a: 0, why: "La estructura del tanque queda alta incluso vacía. No trate lo vacío como automáticamente estable." },
  { id: "tk-12", category: "tanker", topic: "Arranque/parada", q: "Al arrancar una cisterna cargada en una pendiente:", choices: ["Suelte los frenos con suavidad y aplique potencia sin tirones, lo que puede iniciar el oleaje", "Suelte el clutch de golpe", "Use solo los frenos del tráiler a 30 mph", "Deje que ruede hacia atrás primero"], a: 0, why: "Los arranques y paradas bruscos mueven el líquido. La potencia y el frenado suaves son lo básico de conducir cisternas." },
  { id: "tk-13", category: "tanker", topic: "Oleaje lateral", q: "El oleaje de lado a lado es especialmente peligroso porque puede:", choices: ["Causar una volcadura", "Llenar los tanques de aire", "Cerrar la quinta rueda", "Enfriar los frenos"], a: 0, why: "El líquido que golpea un lado en una curva o un cambio de carril aumenta el riesgo de volcadura. Los deflectores ayudan menos con el oleaje lateral de lo que algunos conductores creen." },
  { id: "tk-14", category: "tanker", topic: "Portátiles", q: "Los tanques portátiles en un camión:", choices: ["Deben estar sujetos correctamente; igual pueden olear y tienen un CG alto", "Nunca necesitan un endoso", "Pueden dejarse sin seguro", "Están exentos de fugas"], a: 0, why: "Los tanques portátiles que cumplen las reglas de capacidad igual necesitan el endoso N y deben asegurarse contra el movimiento." },
  { id: "tk-15", category: "tanker", topic: "Nunca llenar", q: "Nunca debe cargar un tanque completamente lleno porque:", choices: ["El líquido se expande con la temperatura; sin espacio vacío el tanque puede desbordarse o sobrepresurizarse", "Reduce el oleaje a cero", "DOT prohíbe todas las cargas parciales", "El ABS no funcionará"], a: 0, why: "Deje el espacio vacío requerido. El espacio de expansión es un requisito legal y de seguridad." },

  { id: "hz-01", category: "hazmat", topic: "Rótulos", q: "Un vehículo rotulado debe tener por lo menos ¿cuántos rótulos idénticos?", choices: ["2", "3", "4", "8"], a: 2, why: "Frente, parte trasera y ambos lados: legibles desde las cuatro direcciones." },
  { id: "hz-02", category: "hazmat", topic: "Forma", q: "Los rótulos de HazMat son:", choices: ["Diamantes en punta de por lo menos 9.84 pulgadas (250 mm)", "Calcomanías redondas de 3 pulgadas", "Solo en los documentos de embarque", "Opcionales si conduce despacio"], a: 0, why: "Con forma de diamante, 250 mm, de pie sobre una punta." },
  { id: "hz-03", category: "hazmat", topic: "Endoso", q: "Para conducir un vehículo que requiere rótulos de HazMat usted necesita:", choices: ["Ninguna prueba extra", "Un CDL con endoso H y una evaluación de amenaza a la seguridad de TSA", "Solo una licencia de auto Clase C", "Solo conocimientos de frenos de aire"], a: 1, why: "Prueba de conocimientos del endoso H más la verificación de antecedentes de TSA. X es H más cisterna." },
  { id: "hz-04", category: "hazmat", topic: "Documentos", q: "Los documentos de embarque de HazMat deben estar:", choices: ["Encima de los demás papeles y en el lugar requerido en la cabina para que se encuentren rápido después de un choque", "Solo en un tráiler cerrado con llave", "Enviados por correo a DOT antes de cada viaje", "Opcionales si está rotulado"], a: 0, why: "Los equipos de emergencia necesitan los documentos. Guárdelos en la bolsa de la puerta del conductor, en el asiento o según indiquen las reglas: no enterrados." },
  { id: "hz-05", category: "hazmat", topic: "ERG", q: "La Guía de respuesta en caso de emergencia (ERG) se usa para:", choices: ["Identificar peligros y el aislamiento/respuesta inicial de un material usando el número de identificación o el nombre", "Calcular el impuesto al combustible", "Ajustar los ajustadores de holgura", "Acoplar los conectores glad hands"], a: 0, why: "Los números de ID UN/NA en los documentos y los paneles naranjas/rótulos se relacionan con las guías ERG." },
  { id: "hz-06", category: "hazmat", topic: "Clases", q: "¿Cuántas clases de materiales peligrosos de DOT hay?", choices: ["3", "6", "9", "12"], a: 2, why: "Clases 1–9: explosivos, gases, líquidos inflamables, sólidos inflamables, oxidantes/peróxidos orgánicos, tóxicos, radiactivos, corrosivos, misceláneos." },
  { id: "hz-07", category: "hazmat", topic: "Humo", q: "No debe fumar a menos de 25 pies de un vehículo cuando contiene:", choices: ["Explosivos Clase 1, líquidos inflamables Clase 3 o gas inflamable, entre otros materiales listados", "Solo agua embotellada", "Solo cajas vacías selladas sin residuo", "Solo muebles"], a: 0, why: "No fumar cerca de muchas clases de peligro. Conozca la regla de 25 pies de la Sección 9." },
  { id: "hz-08", category: "hazmat", topic: "Carga", q: "Al cargar HazMat usted debe:", choices: ["Seguir las reglas de segregación para que no se carguen juntos materiales incompatibles", "Mezclar todas las clases para ahorrar espacio", "Siempre cargar explosivos con oxidantes", "Dejar los paquetes sin asegurar para ventilación"], a: 0, why: "Las tablas de segregación prohíben ciertas combinaciones. Asegure los paquetes contra el movimiento." },
  { id: "hz-09", category: "hazmat", topic: "Llantas", q: "En un vehículo rotulado, si tiene una llanta dual sobrecalentada usted debe:", choices: ["Quedarse con el vehículo hasta que la llanta se enfríe; una llanta sobrecalentada puede causar un incendio o una explosión con algunas cargas", "Conducir más rápido para enfriarla", "Estacionarse en un túnel", "Ignorarla si la otra dual está bien"], a: 0, why: "Deténgase y enfríe las llantas sobrecalentadas. No continúe con una llanta peligrosa en una carga de HazMat." },
  { id: "hz-10", category: "hazmat", topic: "Túnel", q: "Algunos HazMat están restringidos de:", choices: ["Túneles, ciertos puentes y rutas listadas en los reglamentos o en el documento de embarque", "Todos los estacionamientos", "Todas las carreteras de dos carriles", "Todas las estaciones de pesaje"], a: 0, why: "Existen restricciones de ruta. Siga las instrucciones del expedidor y las reglas federales/estatales." },
  { id: "hz-11", category: "hazmat", topic: "Fugas", q: "Si descubre una fuga o un derrame de HazMat:", choices: ["Siga los procedimientos de emergencia, mantenga a las personas alejadas y use los documentos de embarque/ERG; no transvase el producto a menos que esté entrenado y sea seguro", "Oculte la fuga y termine la entrega", "Pruebe el producto para identificarlo", "Lávelo hacia un drenaje pluvial"], a: 0, why: "Proteja la vida primero. Avise a otros, notifique a los servicios de emergencia y no tome acciones para las que no está entrenado." },
  { id: "hz-12", category: "hazmat", topic: "Quién", q: "¿Quién certifica que un envío de HazMat se ofrece correctamente (empacado, marcado, etiquetado, documentado)?", choices: ["El expedidor", "Cualquier conductor que pase", "Solo el empleado del mostrador de combustible", "El fabricante del tráiler"], a: 0, why: "El expedidor certifica. El transportista/conductor no debe aceptar un envío inadecuado y debe revisar documentos, rótulos y carga." },
  { id: "hz-13", category: "hazmat", topic: "Aceptar", q: "Un conductor no debe aceptar una carga de HazMat si:", choices: ["Los paquetes están dañados, gotean, o los documentos/rótulos faltan o están mal", "El expedidor lo certificó, sin importar fugas evidentes", "Está lloviendo", "El tanque tiene el espacio vacío adecuado"], a: 0, why: "No acepte HazMat que gotee o esté preparado de forma inadecuada. Usted comparte la responsabilidad una vez que toma la carga." },
  { id: "hz-14", category: "hazmat", topic: "Número de ID", q: "Un número de ID UN/NA de 4 dígitos:", choices: ["Identifica el material para los equipos de emergencia y puede aparecer en rótulos o paneles naranjas", "Es el número de CDL del conductor", "Es el VIN del tractocamión", "Reemplaza los documentos de embarque"], a: 0, why: "Los números de ID están en los documentos de embarque y a menudo en el vehículo. Úselos con la ERG." },
  { id: "hz-15", category: "hazmat", topic: "Vacío", q: "Los tanques o paquetes vacíos que todavía contienen residuo de HazMat:", choices: ["Pueden seguir regulados y aún necesitar rótulos hasta que se limpien/purgue según se requiera", "Nunca son HazMat", "Siempre pueden marcarse como carga general", "No necesitan sujeción"], a: 0, why: "El residuo todavía puede ser peligroso. Vacío no significa automáticamente no regulado." },

  { id: "ps-01", category: "passenger", topic: "Vías", q: "Los autobuses deben detenerse en los cruces ferroviarios:", choices: ["Entre 15 y 50 pies del riel más cercano, mirar y escuchar, y luego cruzar sin cambiar de marcha", "Solo si se ve un tren", "Sobre las vías si hay tráfico adelante", "A 55 mph si las luces no destellan"], a: 0, why: "Deténgase a 15–50 pies del riel más cercano (con las excepciones listadas) y luego cruce en una marcha que no requiera cambiar." },
  { id: "ps-02", category: "passenger", topic: "Puente levadizo", q: "En un puente levadizo sin señal ni encargado, un autobús debe:", choices: ["Detenerse por lo menos 50 pies antes del tramo móvil y no continuar hasta que esté completamente cerrado", "Nunca detenerse", "Acelerar", "Tocar el claxon y continuar"], a: 0, why: "Los puentes levadizos sin control requieren una parada de por lo menos 50 pies antes del tramo móvil." },
  { id: "ps-03", category: "passenger", topic: "Pasajero de pie", q: "Ningún pasajero puede estar de pie:", choices: ["Delante de la línea de pasajeros de pie o de un modo que bloquee la visión del conductor", "En el pasillo jamás, en ningún autobús", "Solo si tiene un boleto", "Detrás del eje trasero"], a: 0, why: "Mantenga despejada la vista y los controles del conductor. Siga las reglas de la línea de pasajeros de pie y del pasillo." },
  { id: "ps-04", category: "passenger", topic: "Salidas", q: "Las salidas de emergencia deben estar:", choices: ["Operativas, rotuladas y nunca bloqueadas por pasajeros o carga", "Atadas cerradas a velocidades de carretera", "Usadas como almacenamiento", "Cerradas con llave solo desde afuera"], a: 0, why: "Las salidas de emergencia bloqueadas o inoperantes son una infracción grave y un punto de la prueba." },
  { id: "ps-05", category: "passenger", topic: "Combustible", q: "No debe recargar un autobús:", choices: ["En un edificio cerrado con pasajeros a bordo, o con el motor encendido (siga las reglas del manual)", "En ninguna parada de camiones jamás", "Con el freno de estacionamiento puesto", "Durante el día"], a: 0, why: "Cargar combustible con pasajeros a bordo en un edificio cerrado está prohibido. Evite cargar con pasajeros a bordo excepto según se permita específicamente." },
  { id: "ps-06", category: "passenger", topic: "Conteo", q: "Al llegar al destino o a paradas intermedias, un conductor profesional de autobús debe:", choices: ["Asegurarse de que se rinda cuenta de los pasajeros y de que no quede nada que cree un peligro", "Irse de inmediato sin mirar", "Encerrar a los pasajeros", "Apagar todas las luces, incluidas las de gálibo, al descargar en la vía"], a: 0, why: "Evite dejar personas o artículos peligrosos. Supervise el descenso." },
  { id: "ps-07", category: "passenger", topic: "Excepción ferroviaria", q: "Un autobús no está obligado a detenerse en un cruce ferroviario si:", choices: ["El cruce está marcado como exento o está controlado de un modo que el manual lista como excepción, como un semáforo o un encargado que dirige el tráfico", "El autobús va atrasado", "Los pasajeros votan por continuar", "Es un autobús escolar"], a: 0, why: "Conozca las excepciones listadas (señales de exento, controlado por semáforo, etc.). Los autobuses escolares tienen sus propias reglas más estrictas." },
  { id: "ps-08", category: "passenger", topic: "Suavidad", q: "La comodidad y la seguridad de los pasajeros requieren:", choices: ["Arranques, paradas y giros suaves para que las personas no salgan lanzadas", "Aceleración máxima desde cada parada", "Frenado fuerte para entrenar a los pasajeros a agarrarse", "Puertas de emergencia abiertas en la carretera"], a: 0, why: "Los pasajeros no están sujetos como la carga. Conduzca con más suavidad que con flete." },
  { id: "ps-09", category: "passenger", topic: "Evacuación", q: "Si debe evacuar un autobús:", choices: ["Deténgase en un lugar seguro, explique y use las salidas más seguras; mantenga a las personas en grupo lejos del tráfico y del autobús si hay incendio o peligro", "Deje a los pasajeros en el autobús en un incendio", "Evacue hacia los carriles de tráfico", "Oculte los documentos de embarque"], a: 0, why: "Dirija la evacuación. El incendio, la seguridad y la posición en la vía determinan qué salidas usar." },
  { id: "ps-10", category: "passenger", topic: "Prohibido", q: "¿Cuál es una práctica prohibida común en un autobús?", choices: ["Permitir que los pasajeros ocupen el pozo de los escalones cuando el autobús se mueve", "Usar los espejos", "Anunciar las paradas", "Usar el cinturón de seguridad"], a: 0, why: "Las puertas y los pozos de los escalones deben estar despejados. Los pasajeros en el pozo de los escalones pueden caerse." },
  { id: "ps-11", category: "passenger", topic: "Inspección", q: "Una inspección previa al viaje de un vehículo de pasajeros incluye atención extra a:", choices: ["Asientos, salidas de emergencia, dispositivos de señalización y peligros del área de pasajeros", "Solo la quinta rueda", "Solo la grasa del perno rey", "Solo los deflectores de cisterna"], a: 0, why: "La Sección 4 agrega elementos del compartimento de pasajeros y del equipo de emergencia a la inspección básica." },
  { id: "ps-12", category: "passenger", topic: "Puente", q: "Si un autobús se queda parado en las vías del ferrocarril usted debe:", choices: ["Evacuar de inmediato y alejar a las personas de las vías, y luego contactar al ferrocarril si es posible", "Quedarse a bordo y esperar", "Intentar empujar el autobús con pasajeros todavía en el pasillo", "Acostarse en las vías para señalar"], a: 0, why: "Saque a las personas y aléjelas. Un tren no puede detenerse a tiempo." },

  { id: "pt-01", category: "pretrip", topic: "Acercamiento", q: "Al acercarse al vehículo para inspeccionarlo, debe buscar:", choices: ["Fugas debajo del vehículo, inclinación/daños y peligros alrededor (personas, objetos, cables bajos)", "Solo si es su color favorito", "Solo la marca del combustible", "Solo las emisoras preestablecidas de la radio interior"], a: 0, why: "El paso 1 del método de 7 pasos empieza antes de tocar la cabina." },
  { id: "pt-02", category: "pretrip", topic: "Motor", q: "Las revisiones del compartimento del motor incluyen:", choices: ["Fugas, niveles de aceite/refrigerante/dirección hidráulica/combustible, bandas, mangueras y piezas sueltas", "Solo el claxon", "Solo el tinte del parabrisas", "Solo los sellos de la carga"], a: 0, why: "Los fluidos, las bandas, las mangueras y las fugas son elementos centrales del compartimento del motor." },
  { id: "pt-03", category: "pretrip", topic: "Aceite", q: "Al revisar el aceite del motor debe confirmar:", choices: ["El nivel correcto y que no haya una fuga visible", "Que falta la varilla medidora", "La banda de las llantas", "La altura del tráiler"], a: 0, why: "El aceite bajo o una fuga es un no-go hasta que se corrija." },
  { id: "pt-04", category: "pretrip", topic: "Dirección", q: "Los componentes de la dirección deben estar:", choices: ["Montados de forma segura, no dañados ni faltantes, sin holgura excesiva", "Solo del mismo color de pintura", "Sueltos para girar más fácil", "Desconectados"], a: 0, why: "Nombre las piezas (caja de dirección, varillaje, mangueras, bomba) y explique qué sería un defecto." },
  { id: "pt-05", category: "pretrip", topic: "Suspensión", q: "Los muelles de hoja y la suspensión deben revisarse por:", choices: ["Grietas, hojas faltantes, desplazamiento, bolsas de aire con fugas y pernos en U/soportes seguros", "Nivel de combustible", "Recepción de radio", "Solo ventanas limpias"], a: 0, why: "Los muelles rotos, la suspensión de aire con fugas y los soportes sueltos son elementos fuera de servicio." },
  { id: "pt-06", category: "pretrip", topic: "Llantas", q: "La inspección de las llantas incluye:", choices: ["Inflado, profundidad de la banda, costados, separación de duales y daños (cortes, abultamientos, tela visible)", "Solo el nombre de la marca", "Solo el color", "Solo el estilo de las tapas de las válvulas"], a: 0, why: "Llantas de dirección 4/32\", las demás 2/32\", sin recauchutados en el eje de dirección de algunos vehículos, duales coincidentes." },
  { id: "pt-07", category: "pretrip", topic: "Ruedas", q: "Las ruedas y los rines deben inspeccionarse por:", choices: ["Grietas, anillos de cierre fuera de asiento, espárragos faltantes/sueltos y fugas de los sellos del cubo", "Limpiaparabrisas", "Solo las puertas del tráiler", "Bandas del motor"], a: 0, why: "Un rin agrietado o un espárrago faltante puede perder una rueda. Las fugas de aceite/grasa del cubo también importan." },
  { id: "pt-08", category: "pretrip", topic: "Cámaras", q: "Las cámaras de freno deben estar:", choices: ["Montadas de forma segura, no agrietadas, sin fugas de aire", "Usadas como escalones", "Cubiertas de aceite", "Desconectadas para la prueba en carretera"], a: 0, why: "Las cámaras dañadas o los pernos de enjaulado con fugas son defectos. Mencione la carrera de la varilla de empuje si se lo piden." },
  { id: "pt-09", category: "pretrip", topic: "Luces", q: "La inspección de iluminación debe verificar:", choices: ["Que faros, gálibos, marcadores, direccionales, frenos, 4 intermitentes y reflectores estén limpios y funcionen", "Solo los faros", "Solo las luces interiores", "Solo un marcador"], a: 0, why: "Recorra el vehículo. Pida a un ayudante o use reflejos para ver las luces de freno." },
  { id: "pt-10", category: "pretrip", topic: "Seguridad en cabina", q: "El equipo de seguridad en cabina que debe estar presente incluye:", choices: ["Extintor, dispositivos de advertencia y fusibles de repuesto si se requieren", "Solo agua embotellada", "Solo una linterna", "Solo herramientas"], a: 0, why: "Señale el extintor (cargado, con clasificación, montado) y los triángulos." },
  { id: "pt-11", category: "pretrip", topic: "Cinturón", q: "El cinturón de seguridad del conductor debe estar:", choices: ["Montado de forma segura, no cortado ni deshilachado, y abrochado correctamente", "Metido detrás del asiento", "Usado solo en autopistas", "Decorativo"], a: 0, why: "Se le exigirá usarlo. Inspecciónelo durante las revisiones en cabina." },
  { id: "pt-12", category: "pretrip", topic: "Espejos", q: "Los espejos deben estar:", choices: ["Seguros, limpios y ajustados antes de moverse", "Plegados para aerodinámica al conducir en la ciudad", "Retirados", "Sueltos para que vibren"], a: 0, why: "Ajuste antes de la prueba de destrezas para que pueda ver ambos lados y hacia atrás." },
  { id: "pt-13", category: "pretrip", topic: "Parabrisas", q: "El parabrisas debe estar:", choices: ["Limpio, sin daños en la vista del conductor, con limpiaparabrisas y lavadores funcionando", "Cubierto de calcomanías en el área de visión", "Polarizado lo más oscuro posible al frente", "Agrietado mientras pueda ver alrededor"], a: 0, why: "Las calcomanías ilegales y las grietas en el área crítica de visión reprueban la inspección." },
  { id: "pt-14", category: "pretrip", topic: "Pruebas de aire", q: "Las pruebas de frenos de aire en cabina requeridas en la prueba de destrezas típicamente incluyen:", choices: ["Fuga aplicada, advertencia de aire bajo y salida de los frenos de resorte/protección del tractor (más acumulación según se requiera)", "Solo tocar el claxon", "Solo una prueba de tirón", "Solo revisar la radio"], a: 0, why: "Debe demostrar y verbalizar los parámetros. Omitir una prueba de aire requerida es una reprobación automática de la inspección." },
  { id: "pt-15", category: "pretrip", topic: "Verbalizar", q: "Durante la prueba de inspección del CDL usted debe:", choices: ["Señalar o tocar cada elemento, nombrarlo y explicar qué busca y por qué importa", "Caminar en silencio alrededor del camión", "Inspeccionar solo el lado izquierdo", "Omitir el acoplamiento si se ve bien"], a: 0, why: "Los examinadores califican lo que muestra y dice. Las miradas silenciosas no cuentan." },
  { id: "pt-16", category: "pretrip", topic: "Inspección de acoplamiento", q: "La inspección de combinación de la quinta rueda incluye:", choices: ["Montaje, grasa, sin holgura, mandíbulas en el vástago del perno rey, brazo de liberación asentado, seguro de seguridad enganchado", "Solo que el tráiler sea un furgón seco", "Solo la marca de las llantas", "Solo la tapa del combustible"], a: 0, why: "La Sección 6.5 y la hoja de calificación de la prueba de destrezas enfatizan una revisión completa del acoplamiento." },
  { id: "pt-17", category: "pretrip", topic: "Inspección de patas de apoyo", q: "Las patas de apoyo deben estar:", choices: ["Completamente levantadas, sin piezas faltantes, manivela asegurada, marco de apoyo no dañado", "Abajo en la carretera", "Lo suficientemente sueltas para traquetear", "Doblado es aceptable"], a: 0, why: "Las patas dañadas o abajo pueden engancharse en el camino o fallar en un embarcador." },
  { id: "pt-18", category: "pretrip", topic: "Puertas", q: "Las puertas del tráiler, las amarras y el área de carga deben revisarse para que:", choices: ["Las puertas estén cerradas/con seguro o la carga contenida, y nada se derrame ni se caiga", "Las puertas puedan abrirse libremente en la carretera", "El sello esté roto si tiene curiosidad", "Solo importe la puerta izquierda"], a: 0, why: "Las puertas sin asegurar y la carga que gotea/cae son puntos de inspección y en ruta." },
  { id: "pt-19", category: "pretrip", topic: "Inspección de escape", q: "El escape debe estar:", choices: ["Seguro, sin fugas y sin tocar cables, combustible ni líneas de aire", "Parcheado con cinta como reparación normal", "Enrutado a través de la cabina para calor", "Desconectado para ahorrar contrapresión"], a: 0, why: "Las fugas envenenan la cabina; el contacto con combustible o líneas de aire es un peligro de incendio/frenos." },
  { id: "pt-20", category: "pretrip", topic: "Intentos", q: "Para la prueba de destrezas del CDL de California, se le permiten hasta ¿cuántos intentos para los componentes de inspección, control básico y prueba en carretera?", choices: ["Uno en total", "Tres intentos (aplican cuotas de repetición; reprobar una parte pospone el resto ese día según describe el DMV)", "Ilimitados el mismo día", "Diez"], a: 1, why: "DMV: tres intentos para aprobar la prueba de destrezas. Si reprueba una porción, se pospone el resto de las pruebas. Aplican cuotas de repetición." }
];
